KB.lade("westafrika",[{"id":"westafrika-jollof-rice","name":"Jollof Rice (Party-Jollof nach nigerianischer Art)","originalname":"Jollof Rice","kueche":"westafrika","region":"Nigeria","beliebtheit":94,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Leuchtend rotes, rauchig-würziges Reisgericht aus einer eingekochten Tomaten-Paprika-Basis – Festessen und Streitobjekt ganz Westafrikas.","hintergrund":"Jollof geht auf das Wolof-Reich im heutigen Senegal zurück, wo der Reiseintopf Thieboudienne heißt, und ist heute das Nationalgericht-Streitthema zwischen Nigeria, Ghana, Senegal und Co. Die nigerianische Version setzt auf langkörnigen Parboiled-Reis, eine lange eingekochte Basis aus Tomaten, roten Paprika und Scotch Bonnet sowie Lorbeer, Thymian und Curry. Der leicht angebrannte Bodensatz („Party-Jollof“, „Smoky Bottom“) gilt als Qualitätsmerkmal. Ohne Jollof gibt es in Lagos keine Hochzeit, keine Taufe und keine Geburtstagsfeier. Nigerianische Medien führen Jollof Rice unter den zehn beliebtesten Gerichten Afrikas.","portionen":6,"zeit":{"vorbereitung":30,"garen":100,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für das Hähnchen","liste":[{"menge":8,"einheit":"Stück","name":"Hähnchenschenkel oder Keulen, bone-in","hinweis":"ca. 1,2 kg; Haut dran für mehr Geschmack"},{"menge":2,"einheit":"TL","name":"Currypulver (mild, westafrikanisch oder Madras)","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Thymian","hinweis":""},{"menge":1,"einheit":"TL","name":"Knoblauchpulver","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""}]},{"gruppe":"Für die Basis","liste":[{"menge":6,"einheit":"Stück","name":"reife Tomaten (Roma/Fleischtomaten)","hinweis":"oder 1 Dose (400 g) Tomaten plus 3 frische"},{"menge":3,"einheit":"Stück","name":"rote Spitzpaprika","hinweis":"in Nigeria „tatashe“; ersatzweise rote Paprika"},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet oder Habanero","hinweis":"Menge nach Schärfe-Toleranz, Bonnets sind sehr scharf; im Asia-/Afro-Laden erhältlich"},{"menge":2,"einheit":"Stück","name":"große Zwiebeln","hinweis":"eine für die Basis, eine zum Anbraten"}]},{"gruppe":"Für den Reis","liste":[{"menge":5,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":3,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":2,"einheit":"TL","name":"Currypulver","hinweis":""},{"menge":2,"einheit":"TL","name":"getrockneter Thymian","hinweis":""},{"menge":1,"einheit":"TL","name":"Paprikapulver, geräuchert","hinweis":"für den Rauchgeschmack"},{"menge":2,"einheit":"Stück","name":"Brühwürfel (Hühnerbrühe)","hinweis":"oder 2 EL Brühpulver"},{"menge":500,"einheit":"ml","name":"Hühnerbrühe","hinweis":"heiß"},{"menge":500,"einheit":"g","name":"Parboiled-Langkornreis","hinweis":"keine Basmati-Feinheit – Parboiled bleibt körnig"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["schwerer Topf mit gut schließendem Deckel","Stabmixer oder Standmixer","Alufolie oder Backpapier","große Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alles ab und stelle es in Reichweite, denn Jollof geht später schnell. Vierteile die Tomaten, entkerne die Paprika und schneide beides grob, die Zwiebeln schälst du: eine halbierst du für den Mixer, die andere schneidest du in feine Halbringe (ca. 3 mm). Die Scotch Bonnet halbierst du mit Handschuhen und gibst sie zunächst ganz hinein, später kannst du nachwürzen. Wasche den Parboiled-Reis noch nicht; das machst du erst kurz vor dem Einrühren. Heize den Ofen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor, falls du das Hähnchen im Ofen fertig garen willst.","dauer":15,"tipp":"Handschuhe beim Entkernen der Scotch Bonnet – die Schärfe bleibt stundenlang an den Fingern."},{"titel":"Hähnchen würzen","aktion":"marinieren","text":"Reibe die Hähnchenteile mit Curry, Thymian, Knoblauchpulver und Salz gründlich ein und massiere die Gewürze bis unter die Haut. Lasse das Fleisch mindestens 20 Minuten bei Zimmertemperatur ziehen, besser eine Stunde im Kühlschrank. Das Salz zieht in dieser Zeit tief ein und würzt das Fleisch von innen, der Curry bildet später eine goldgelbe Kruste. Nimm das Fleisch vor dem Braten raus, damit es nicht eiskalt in die Pfanne kommt und Hitze verliert.","dauer":20,"tipp":""},{"titel":"Hähnchen anbraten","aktion":"anbraten","text":"Erhitze 2 EL Öl in einer großen Pfanne mittelhoch, bis es leicht flimmert. Lege die Hähnchenteile mit der Hautseite nach unten hinein und brate sie ohne Bewegen 5–6 Minuten, bis die Haut tief goldbraun ist und sich vom Pfannenboden löst. Wende und brate die andere Seite 3 Minuten an. Das Fleisch muss noch nicht durch sein – es gart später im Reis weiter. Stelle es beiseite und lasse das Bratfett samt Röststoffen in der Pfanne, du brauchst es gleich für die Basis.","dauer":10,"tipp":"Nicht zu viele Teile gleichzeitig in die Pfanne, sonst dämpft das Fleisch statt zu bräunen."},{"titel":"Tomaten-Paprika-Basis pürieren","aktion":"puerieren","text":"Gib Tomaten, Paprika, die halbe Zwiebel und die Scotch Bonnet in den Mixer und püriere alles sehr fein, bis eine glatte, leuchtend rote Flüssigkeit entsteht. Schmecke nicht ab, sie ist noch roh und wässrig. Miss die Menge: Du solltest etwa 800 ml bis 1 Liter haben. Zu viel Flüssigkeit macht den Reis matschig, deshalb kochst du sie im nächsten Schritt ein.","dauer":5,"tipp":""},{"titel":"Zwiebeln und Tomatenmark rösten","aktion":"anbraten","text":"Erhitze das Öl für den Reis (5 EL) im schweren Topf mittelhoch, gib die Zwiebelhalbringe hinein und brate sie 5–6 Minuten, bis sie weich und an den Rändern goldbraun sind. Füge das Tomatenmark hinzu und röste es unter ständigem Rühren 3–4 Minuten, bis es dunkelrot bis rostbraun wird und süßlich duftet. Dieses Anrösten nimmt dem Mark die Säure und ist der Grundstein für die tiefrote Farbe. Brennt es an den Rändern an, sofort die Hitze reduzieren.","dauer":10,"tipp":""},{"titel":"Basis einkochen","aktion":"reduzieren","text":"Gieße die pürierte Basis zu den Zwiebeln, rühre den Röstansatz vom Boden los und lasse alles offen bei mittlerer Hitze köcheln. Rühre alle paar Minuten um, bis die Menge um mehr als die Hälfte reduziert ist – das dauert 25–30 Minuten. Du erkennst das Ziel daran, dass sich Öl an der Oberfläche absetzt, die Sauce dunkler und dicker wird und kein „frischer“ Tomatengeruch mehr in der Luft liegt. Fehlt dieses Einkochen, schmeckt Jollof flach und sauer.","dauer":30,"tipp":"Ein Spritzschutz oder ein leicht schräg aufgelegter Deckel hält die Küche sauber."},{"titel":"Würzen","aktion":"abschmecken","text":"Rühre Lorbeer, Curry, Thymian, geräuchertes Paprikapulver und die zerbröselten Brühwürfel in die eingekochte Basis. Gieße 500 ml heiße Hühnerbrühe dazu, bringe alles zum Kochen und probiere. Die Flüssigkeit sollte kräftig, leicht scharf und eher zu salzig als zu fad schmecken, denn der Reis nimmt viel Würze auf. Entferne die Scotch Bonnet, wenn es dir scharf genug ist, oder zerdrücke sie leicht, wenn du mehr Feuer willst.","dauer":5,"tipp":""},{"titel":"Reis waschen und einrühren","aktion":"mischen","text":"Spüle den Parboiled-Reis in einem Sieb unter kaltem Wasser, bis es klarer abläuft – das spült überschüssige Stärke ab, sodass der Reis später körnig bleibt. Gib ihn in die kochende Sauce, verteile ihn gleichmäßig und rühre ein einziges Mal gründlich. Die Flüssigkeit soll den Reis nur knapp bedecken (ca. 1 cm). Lege die angebratenen Hähnchenteile obenauf, sodass sie zur Hälfte eintauchen. Danach wird nicht mehr gerührt, sonst verkleistert der Reis.","dauer":5,"tipp":""},{"titel":"Abgedeckt dämpfen","aktion":"daempfen","text":"Lege ein Stück Alufolie oder Backpapier direkt auf den Reis, drücke es an den Rändern fest und setze den Deckel schwer darauf. Stelle die Hitze auf die niedrigste Stufe und lasse den Reis 30–35 Minuten gedämpft garen. Du hörst anfangs leises Brodeln, später ein sanftes Knistern am Boden. Nach 20 Minuten hebst du Folie und Deckel kurz an und lockerst die obere Schicht vorsichtig mit einer Gabel, damit Dampf entweichen kann. Ist der Reis noch hart, gib 50 ml heißes Wasser dazu und dämpfe 10 Minuten weiter. Ein leichter Röstgeruch ist gewollt – Brandgeruch nicht.","dauer":35,"tipp":"Der „Smoky Bottom“ entsteht in den letzten 5 Minuten bei etwas höherer Hitze; unten soll der Reis nur leicht angeröstet, nicht verkohlt sein."},{"titel":"Ruhen und lockern","aktion":"ruhen","text":"Nimm den Topf vom Herd, lasse ihn mit geschlossenem Deckel 10 Minuten stehen und entferne dann die Folie. Der Reis zieht im Restdampf nach und wird gleichmäßig. Lockere ihn mit einer Gabel von den Rändern nach innen auf und prüfe: Die Körner sollen einzeln, glänzend rotorange und bissfest sein. Stecke ein Thermometer in ein Hähnchenteil – es soll 78–80 °C erreichen, bevor du servierst; sonst gib es im 180-°C-Ofen 10 Minuten nach.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schmecke den Reis ein letztes Mal mit Salz ab. Richte ihn auf einer großen Platte an und lege die Hähnchenteile obenauf. Serviere nach nigerianischer Tradition mit frittierten Kochbananen (Dodo), einem Tomaten-Zwiebel-Salat und, wenn du magst, Moi-Moi oder Coleslaw. Der Reis schmeckt aufgewärmt am nächsten Tag noch besser, weil sich die Aromen setzen.","dauer":0,"tipp":""}],"profitipps":["Die Basis muss lange einkochen: Erst wenn sich das Öl absetzt, ist der Rohgeschmack weg und die Farbe satt.","Parboiled-Reis ist das Geheimnis der Körnigkeit; Basmati und Rundkornreis werden schnell weich oder klebrig.","Nach dem Einrühren des Reises nicht mehr rühren; Folie unter dem Deckel fängt den Dampf und verhindert Verbrennen.","Tomatenmark kräftig anrösten – es liefert Süße und Farbe.","Für den Rauchgeschmack: geräuchertes Paprikapulver oder eine kurz angebrannte Bodenschicht, nie Flüssigrauch."],"varianten":["Ghanaisches Jollof mit Basmati-/Duftreis, Ingwer und Fisch oder Rindfleisch","Senegalesisches Thieboudienne mit Fisch, Maniok und Gemüse","Vegetarisches Jollof mit Gemüsebrühe und gebratenen Kochbananen"],"beilagen":["frittierte Kochbananen (Dodo)","Moi-Moi","Krautsalat","gegrilltes Hähnchen"],"getraenk":"Eiskaltes Malzgetränk, Zobo (Hibiskusgetränk) oder ein kräftiges Lagerbier","koeche":[],"quellen":[{"titel":"BusinessDay – Where jollof rice ranks in Africa's best 10 dishes","url":"https://businessday.ng/news/article/here-is-where-jollof-rice-ranks-in-africas-best-10-dishes/"},{"titel":"TasteAtlas – Best Rated Dishes in Africa","url":"https://tasteatlas.com/best-rated-dishes-in-africa"},{"titel":"TasteAtlas – Best Rated Dishes in Nigeria","url":"https://www.tasteatlas.com/best-rated-dishes-in-nigeria"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"}],"bild":"reis","farben":["#c1440e","#e8742a","#f2c14e"],"schlagworte":["Party","Westafrika","Reisgericht","Nigeria","scharf"],"vegetarisch_moeglich":true},{"id":"westafrika-thieboudienne","name":"Thieboudienne – Senegals Fisch-Reis-Gericht","originalname":"Ceebu jën / Thiéboudiène","kueche":"westafrika","region":"Senegal (Saint-Louis, Dakar)","beliebtheit":88,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Gefüllter Fisch, buntes Gemüse und Reis, der im tomatigen Fischsud gegart wird und am Topfboden eine knusprige Kruste bildet – das Nationalgericht Senegals.","hintergrund":"Thieboudienne (Wolof: ceebu jën, „Reis mit Fisch“) gilt als Nationalgericht Senegals und wird traditionell zum Mittagessen aus einer großen gemeinsamen Schüssel gegessen. Die Küche der Stadt Saint-Louis hat das Gericht geprägt; der Fisch wird mit einer grünen Kräuterpaste („Rof“) gefüllt, das Gemüse im Sud gegart und der Reis zuletzt in genau dieser Brühe. Der Koch Pierre Thiam nennt das Gericht die „Mutter des Jollof“, weil sie als Vorläufer der späteren Jollof-Varianten Westafrikas gilt. Die knusprige Reiskruste vom Topfboden („xooñ“) ist bei Tisch begehrt und wird unter allen verteilt.","portionen":6,"zeit":{"vorbereitung":60,"garen":100,"ruhen":60},"schwierigkeit":3,"zutaten":[{"gruppe":"Fisch mit Rof-Füllung","liste":[{"menge":1.2,"einheit":"kg","name":"festfleischige Fischsteaks oder -filets (6 Stücke à ca. 200 g)","hinweis":"Zackenbarsch, Wolfsbarsch, Goldbrasse, Rotbarsch oder Kabeljaurücken; Haut darf dranbleiben"},{"menge":1,"einheit":"Bund","name":"glatte Petersilie","hinweis":"Blätter und zarte Stiele"},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"Stück","name":"Frühlingszwiebeln","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":""},{"menge":1,"einheit":"TL","name":"Chiliflocken","hinweis":"oder 1 fein gehackte Scotch Bonnet für mehr Schärfe"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":"frisch gemahlen"}]},{"gruppe":"Sauce und Sud","liste":[{"menge":150,"einheit":"ml","name":"Erdnussöl oder neutrales Pflanzenöl","hinweis":"traditionell auch rotes Palmöl, dann aber nur einen Teil des Öls ersetzen"},{"menge":2,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in feine Halbringe geschnitten"},{"menge":1,"einheit":"Stück","name":"grüne Paprika","hinweis":"in kleine Würfel"},{"menge":130,"einheit":"g","name":"Tomatenmark","hinweis":"dreifach konzentriert"},{"menge":1.8,"einheit":"l","name":"Fischfond oder Gemüsebrühe","hinweis":"heiß halten; zur Not Wasser plus 1 Brühwürfel"},{"menge":2,"einheit":"EL","name":"Tamarindenpaste","hinweis":"Asia- oder Afroshop; Ersatz: Saft von 1 Limette plus 1 TL Zucker"},{"menge":1,"einheit":"EL","name":"Fischsauce","hinweis":"ersetzt den fermentierten Dörrfisch (Guedj), der in Senegal für Tiefe sorgt"},{"menge":1,"einheit":"Stück","name":"Habanero oder Scotch Bonnet","hinweis":"ganz, unverletzt mitgaren – gibt Aroma ohne viel Schärfe"}]},{"gruppe":"Gemüse","liste":[{"menge":4,"einheit":"Stück","name":"Karotten","hinweis":"geschält, in 8 cm lange Stücke"},{"menge":1,"einheit":"Stück","name":"große Aubergine","hinweis":"in dicke Viertel"},{"menge":1,"einheit":"Stück","name":"Mairübe oder weiße Rübe","hinweis":"geviertelt"},{"menge":300,"einheit":"g","name":"Maniok","hinweis":"frisch oder tiefgekühlt, in 5 cm große Stücke; Ersatz: Süßkartoffel"},{"menge":300,"einheit":"g","name":"Weißkohl","hinweis":"in 4 dicke Spalten mit Strunk"},{"menge":6,"einheit":"Stück","name":"Okraschoten","hinweis":"optional, ganz lassen"}]},{"gruppe":"Reis","liste":[{"menge":500,"einheit":"g","name":"Bruchreis (Afroshop) oder Langkornreis","hinweis":"Basmati geht gut; Bruchreis nimmt mehr Sud auf"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"zum Servieren"}]}],"ausruestung":["großer, schwerer Topf (5–6 Liter) mit Deckel","Mörser oder Zerkleinerer für die Rof-Paste","Schaumlöffel","Küchentuch für den Topfdeckel","große Platte zum Anrichten"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle sie in Gruppen bereit, denn Thieboudienne läuft später Schlag auf Schlag. Schneide die Karotten in 8 cm lange Stücke, die Aubergine in dicke Viertel, die Rübe in Viertel, den Maniok in Stücke von etwa 5 cm und den Kohl in vier Spalten mit Strunk – der Strunk hält die Spalten beim Garen zusammen. Schneide die Zwiebeln in feine Halbringe und die Paprika in kleine Würfel. Tupfe den Fisch trocken und lege ihn auf ein Brett; er muss später kalt und trocken in die Füllung, sonst nimmt er sie nicht an.","dauer":20,"tipp":""},{"titel":"Rof-Kräuterpaste herstellen","aktion":"hacken","text":"Hacke Petersilie, Knoblauch, Frühlingszwiebeln und die kleine Zwiebel grob und zerstoße alles mit Salz, Pfeffer und Chili im Mörser zu einer grünen, leicht körnigen Paste. Das Salz wirkt dabei wie Schleifmittel und bricht die Zellen auf, sodass Duft und Saft austreten. Wenn du einen Zerkleinerer nimmst, arbeite in kurzen Impulsen, damit keine nasse Suppe entsteht. Die Paste soll kräftig nach Knoblauch und frischer Petersilie riechen und zusammenhalten, ohne zu triefen. Etwa ein Viertel der Paste bewahrst du für den Sud auf.","dauer":10,"tipp":"Rof ist das Herz des Gerichts: Nicht sparen. Senegalesische Köchinnen stopfen die Füllung so prall, dass sie beim Garen kaum herausfällt."},{"titel":"Fisch füllen und ruhen lassen","aktion":"fuellen","text":"Schneide in jedes Fischstück mit einem scharfen Messer seitlich eine tiefe Tasche, ohne ganz durchzuschneiden, und drücke zwei bis drei Teelöffel Rof hinein. Bei Filets machst du zwei bis drei lange Einschnitte auf der Fleischseite und streichst die Paste hinein. Lege die gefüllten Stücke abgedeckt für mindestens 1 Stunde in den Kühlschrank. In dieser Zeit ziehen Knoblauch und Kräuter ins Fleisch, und der Fisch wird fester, was ihm später beim Braten und Schmoren Halt gibt.","dauer":60,"tipp":""},{"titel":"Fisch anbraten","aktion":"braten","text":"Erhitze die Hälfte des Öls in dem großen Topf bei mittlerer bis hoher Hitze, bis eine Prise Rof darin sofort zischt. Brate die Fischstücke portionsweise 2–3 Minuten pro Seite, bis sie hellgolden sind, und nimm sie danach auf einen Teller. Der Fisch soll nur Farbe und eine feste Außenhaut bekommen und innen noch roh sein, denn er gart später im Sud zu Ende. Gib nicht zu viele Stücke gleichzeitig in den Topf, sonst fällt die Temperatur, und der Fisch kocht statt zu bräunen. Das aromatische Öl bleibt im Topf.","dauer":12,"tipp":"Die Röstaromen am Topfboden sind keine Panne – sie lösen sich später im Sud und machen ihn tiefer."},{"titel":"Zwiebeln und Tomatenmark rösten","aktion":"anbraten","text":"Gib das restliche Öl dazu und dünste Zwiebeln und Paprika bei mittlerer Hitze 8–10 Minuten, bis die Zwiebeln glasig und an den Rändern hellbraun sind. Schiebe sie zur Seite, gib das Tomatenmark in die Mitte und röste es unter ständigem Rühren 6–8 Minuten, bis es von leuchtendem Rot zu einem dunklen, ziegelroten Ton wechselt und sich am Rand Öl absetzt. Dieses Rösten nimmt dem Mark die Säure und das Blechige. Wenn es nach süßlichen, gebratenen Tomaten duftet, bist du richtig; riecht es bitter, war die Hitze zu hoch.","dauer":15,"tipp":""},{"titel":"Sud ansetzen und hartes Gemüse garen","aktion":"kochen","text":"Gieße die heiße Brühe schrittweise zu und rühre den Bodensatz los. Gib die aufgehobene Rof-Paste, die ganze Chilischote, Salz und Pfeffer dazu und bringe den Sud zum Kochen. Lege zuerst die harten Gemüse hinein: Maniok, Karotten und Rübe. Lass alles zugedeckt bei mittlerer Hitze 20 Minuten leise sprudeln, bis eine Messerspitze mühelos in die Karotten einsticht. Der Sud soll kräftig rot sein und nach Tomate und Knoblauch duften.","dauer":20,"tipp":""},{"titel":"Weiches Gemüse nachlegen","aktion":"kochen","text":"Lege Kohl, Aubergine und Okra in den Sud und gare alles weitere 12–15 Minuten zugedeckt. Der Kohl wird weich, behält aber noch Form, die Aubergine soll cremig, aber nicht zerfallen sein. Nimm das gesamte Gemüse vorsichtig mit dem Schaumlöffel heraus und lege es auf eine Platte; decke es mit einem Teller ab, damit es warm bleibt. Der Sud darf nicht dabei auskühlen, denn gleich kommt der Fisch hinein.","dauer":15,"tipp":"Die Gemüsestücke dürfen groß bleiben – in Senegal wird es mit der Hand zerteilt und auf die Reisportion gelegt."},{"titel":"Fisch im Sud garen","aktion":"koecheln","text":"Reduziere die Hitze, bis der Sud nur noch leicht blubbert. Lege die angebratenen Fischstücke hinein und gare sie zugedeckt 8–10 Minuten. Das Fleisch ist fertig, wenn es an der dicksten Stelle seine Glasigkeit verloren hat, sich mit der Gabel in Lamellen löst und etwa 62 °C erreicht. Hebe den Fisch mit einer breiten Schaumkelle heraus und stelle ihn zum Gemüse. Wenn der Sud sprudelt, zerfällt der Fisch, daher nur sanftes Köcheln.","dauer":10,"tipp":""},{"titel":"Sud würzen und Reis garen","aktion":"kochen","text":"Rühre Tamarindenpaste und Fischsauce in den Sud, schmecke ihn mit Salz ab und entferne die Chilischote. Er soll herzhaft, leicht säuerlich und fischig-würzig schmecken – etwas kräftiger als gewünscht, weil der Reis Würze schluckt. Spüle den Reis in mehreren Wassern, bis es klar abläuft, und gib ihn in den Topf. Gieße so viel Sud ab, dass der Reis etwa 1,5 cm hoch bedeckt ist (rund 900 ml), und bringe alles zum Kochen. Der übrige Sud wird zum Servieren aufgehoben.","dauer":5,"tipp":""},{"titel":"Reis dämpfen und Kruste bilden","aktion":"daempfen","text":"Koche den Reis bei mittlerer Hitze, bis kaum noch Flüssigkeit an der Oberfläche steht (ca. 10 Minuten). Lege ein sauberes Tuch unter den Deckel, setze ihn fest auf und gare den Reis bei kleinster Hitze 25–30 Minuten fertig. Röstduft vom Topfboden nach etwa 20 Minuten zeigt an, dass sich die Kruste bildet. Rühre den Reis in dieser Zeit nicht um, sonst wird er matschig und die Kruste bleibt aus. Zum Schluss lockerst du ihn mit der Gabel und löst die Kruste am Boden vorsichtig mit einem Holzlöffel.","dauer":40,"tipp":"Wenn du die Kruste magst, lass den Topf die letzten 5 Minuten bei etwas stärkerer Hitze – Knistern und Röstgeruch zeigen, dass sie gelingt."},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile den roten Reis auf einer großen Platte. Lege den Fisch in die Mitte und ordne das Gemüse darum herum. Die gebrochene Reiskruste legst du als Krönung oben auf oder in eine Extraschale. Serviere den restlichen heißen Sud in einer Schüssel zum Löffeln, dazu Limettenspalten und – wer es scharf mag – eine kleine Schale fein gehackte Chili mit Zwiebeln und Zitronensaft. Traditionell isst man aus der gemeinsamen Schüssel; jeder bedient sich aus seinem Bereich.","dauer":5,"tipp":""}],"profitipps":["Der Reis wird im fertigen Sud gegart: Die Brühe muss vorher kräftig gewürzt sein, sonst schmeckt der Reis fad. Probiere vor dem Reis.","Bruchreis nimmt viel Sud auf und wird weich-feucht; Basmati bleibt körniger. Beides ist authentisch, nur nie klebrigen Rundkornreis nehmen.","Tomatenmark wirklich dunkel rösten – das ist der Unterschied zwischen einem flachen und einem tiefen Thieb.","Fisch nur sanft köcheln und kein zweites Mal umrühren; Steaks von Zackenbarsch oder Kabeljau bleiben saftig, Filets brauchen weniger Zeit.","Für authentische Würze bekommst du in Afroshops getrockneten, fermentierten Fisch (Guedj/Yeet); wer es nicht findet, nimmt Fischsauce wie im Rezept."],"varianten":["Thiéboudienne mit weißer Reisfarbe: ohne Tomatenmark, nur im Fischsud gegart.","Thiébou yapp: Rind- oder Hammelfleisch statt Fisch, von TasteAtlas unter den beliebtesten Gerichten Senegals geführt.","Thiébou guinar mit Hühnchen, wie es bei Familienfesten häufig vorkommt.","Mit Hibiskusblüten (Bissap) im Sud, wie es das Saveur-Rezept vorschlägt, für leichte Säure."],"beilagen":["Limettenspalten","scharfe Chili-Zwiebel-Sauce","Bissap (Hibiskustee)"],"getraenk":"Bissap (kalter Hibiskustee), Ingwersaft oder ein kühles Lagerbier","koeche":[{"name":"Pierre Thiam","bezug":"Der senegalesische Koch bezeichnet Thieboudienne als „Mutter des Jollof“; das Gericht zeigt, wie Fisch, Gemüse und Reis im selben Sud ineinandergreifen.","quelle":"https://www.tastingtable.com/1216347/traditional-west-african-dishes-you-need-to-try-at-least-once/"}],"quellen":[{"titel":"Tasting Table – 12 Traditional West African Dishes","url":"https://www.tastingtable.com/1216347/traditional-west-african-dishes-you-need-to-try-at-least-once/"},{"titel":"Saveur – Senegalese Fish and Rice (Thiéboudienne)","url":"https://www.saveur.com/article/Recipes/Senegal-Fish-Rice/"},{"titel":"TasteAtlas – Best Rated Dishes in Senegal","url":"https://tasteatlas.com/best-rated-dishes-in-senegal"}],"bild":"fisch","farben":["#c0392b","#e67e22","#f5e6c8"],"schlagworte":["Nationalgericht","Senegal","Reispfanne","Familienessen"],"vegetarisch_moeglich":false},{"id":"westafrika-suya","name":"Suya – nigerianische Rindfleischspieße","originalname":"Suya (Tsire)","kueche":"westafrika","region":"Nigeria","beliebtheit":80,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"snack","kurz":"Hauchdünn geschnittenes Rind, in einer Erdnuss-Chili-Gewürzmischung (Yaji) mariniert und über Glut gegrillt, mit rohen Zwiebeln und Tomaten.","hintergrund":"Suya ist das Straßenessen Nordnigerias, ursprünglich von den Hausa. Dünne Rindfleischscheiben werden mit Erdnussmehl, Paprika, Ingwer, Knoblauch und Chili (Yaji, auch Kuli-Kuli-Mix) mariniert und über Holzkohle gegrillt. Man isst Suya abends, in Zeitungspapier gewickelt, mit rohen Zwiebelringen, Tomaten und noch mehr Yaji. Nigerianische Bestenlisten führen die Spieße regelmäßig.","portionen":4,"zeit":{"vorbereitung":30,"garen":15,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch","liste":[{"menge":700,"einheit":"g","name":"Rindfleisch aus der Hüfte oder Rinderfilet","hinweis":"gut parieren, ohne Sehnen"},{"menge":4,"einheit":"EL","name":"Erdnussöl oder Pflanzenöl","hinweis":""}]},{"gruppe":"Yaji-Gewürzmischung","liste":[{"menge":100,"einheit":"g","name":"ungesalzene Erdnüsse","hinweis":"trocken geröstet; Ersatz: Erdnussmehl/Erdnussbutter pur"},{"menge":2,"einheit":"EL","name":"Paprikapulver (edelsüß)","hinweis":""},{"menge":1,"einheit":"EL","name":"Cayennepfeffer oder Chilipulver","hinweis":"nach Schärfe"},{"menge":1,"einheit":"EL","name":"Ingwerpulver","hinweis":""},{"menge":1,"einheit":"EL","name":"Knoblauchpulver","hinweis":""},{"menge":1,"einheit":"EL","name":"Zwiebelpulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"Brühwürfel","hinweis":"zerbröselt"}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"Stück","name":"rote Zwiebeln","hinweis":"in dünne Ringe"},{"menge":3,"einheit":"Stück","name":"Tomaten","hinweis":"in Scheiben"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":""}]}],"ausruestung":["Holzspieße (vorher gewässert)","Grill oder Grillpfanne","Mörser oder Mixer","Gefrierbeutel"],"schritte":[{"titel":"Fleisch parieren und schneiden","aktion":"schneiden","text":"Entferne Sehnen und Fett vom Rind. Lege das Fleisch 20 Minuten ins Gefrierfach, damit es fest wird und sich hauchdünn schneiden lässt. Schneide quer zur Faser Scheiben von ca. 3 mm Dicke und etwa 10 cm Länge. Dünnes Fleisch gart in Sekunden und nimmt die Würzpaste besser an; dickes Fleisch wird zäh und die Kruste verbrennt.","dauer":15,"tipp":""},{"titel":"Yaji-Gewürz herstellen","aktion":"mischen","text":"Röste die Erdnüsse in einer trockenen Pfanne bei mittlerer Hitze 4–5 Minuten, bis sie goldbraun duften, und lasse sie abkühlen. Mahle sie im Mixer zu feinem Pulver, aber nicht zu lange, sonst entsteht Erdnussbutter. Vermische das Erdnusspulver mit allen Gewürzen, Salz und zerbröseltem Brühwürfel. Ein Drittel der Mischung bewahrst du zum Servieren auf.","dauer":10,"tipp":""},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Vermenge das Fleisch mit 4 EL Öl und zwei Dritteln des Yaji, bis jede Scheibe gleichmäßig bedeckt ist. Fülle alles in einen Gefrierbeutel und massiere es durch. Lasse es mindestens 4 Stunden, besser über Nacht im Kühlschrank ziehen. Die Gewürze und das Salz dringen ein und machen das Fleisch zarter.","dauer":240,"tipp":""},{"titel":"Aufspießen","aktion":"formen","text":"Weiche die Holzspieße 30 Minuten in Wasser ein, damit sie nicht verbrennen. Fädele die Fleischscheiben wellenförmig auf die Spieße, so dass sie leicht überlappen. Drücke sie zusammen, damit sie beim Grillen nicht auseinanderfallen. Spieße, die zu dick bepackt sind, garen ungleichmäßig. Arbeite mit trockenen Händen und lege fertige Spieße auf ein Brett, damit nichts abtropft und die Gewürze nicht abgewaschen werden.","dauer":10,"tipp":""},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Bringe den Grill auf hohe Hitze (200–250 °C), die Glut soll gleichmäßig durchgeglüht und weiß belegt sein. Fette den Rost leicht mit einem eingeölten Küchenpapier. In einer Grillpfanne erhitzt du die Pfanne stark, bis sie leicht raucht. Die hohe Hitze sorgt für eine Kruste, ohne dass das Fleisch durchtrocknet.","dauer":5,"tipp":""},{"titel":"Spieße grillen","aktion":"grillen","text":"Lege die Spieße auf den Grill und grille sie 2 Minuten pro Seite, bis das Fleisch am Rand dunkel karamellisiert und leicht angeschwärzt ist. Wende sie nur einmal. Das Fleisch ist dünn und soll durch, aber noch saftig sein. Der Geruch nach geröstetem Erdnuss und Paprika ist das Signal, dass die Kruste perfekt ist.","dauer":8,"tipp":"Nicht pinseln mit zusätzlichem Öl – die Erdnussmischung brennt sonst zu schnell an."},{"titel":"Letzte Würze","aktion":"braten","text":"Streue direkt nach dem Grillen etwas frisches Yaji über die heißen Spieße, damit es in die Oberfläche einzieht. Lasse sie 2 Minuten ruhen, damit sich die Fleischsäfte setzen. Der Geruch nach Röstnuss und Chili soll jetzt intensiv sein. Gib das Gewürz sparsam und gleichmäßig, damit nichts verbrennt oder klumpig bleibt. Wer mehr Schärfe möchte, mischt etwas Cayenne ins Yaji-Schälchen zum Eintauchen.","dauer":2,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere die Spieße auf einer Platte mit rohen Zwiebelringen, Tomatenscheiben und Limettenspalten. Reiche das restliche Yaji in einem Schälchen zum Eintauchen. Bei heißem Wetter passt kaltes Bier oder Malzgetränk perfekt dazu. Traditionell gibt es dazu Wasser in Plastikbeuteln und viel Servietten. Wer keinen Grill hat, brät die Spieße in einer sehr heißen gusseisernen Pfanne in zwei Durchgängen und lässt die Fenster offen, denn es raucht.","dauer":0,"tipp":""}],"profitipps":["Hauchdünn schneiden – dafür das Fleisch leicht anfrieren.","Erdnüsse nur kurz mahlen, sonst wird die Mischung klumpig.","Hohe Hitze, kurze Garzeit: Suya ist ein Schnellgericht.","Frische Gewürzmischung nach dem Grillen für den Röstgeschmack.","Zwiebeln roh dazu – die Schärfe gleicht das Fett aus."],"varianten":["Hähnchen-Suya","Ram-Suya mit Lammfleisch","Gemüse-Suya mit Pilzen"],"beilagen":["Zwiebelringe und Tomaten","Fladenbrot","Kochbananen (Dodo)"],"getraenk":"Kaltes Lagerbier oder Zobo (Hibiskus)","koeche":[],"quellen":[{"titel":"TasteAtlas – Best Rated Dishes in Nigeria","url":"https://www.tasteatlas.com/best-rated-dishes-in-nigeria"},{"titel":"Saiga Tours – Must-Try Foods in Nigeria","url":"https://www.saigatours.com/article/8-must-try-foods-in-nigeria"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"}],"bild":"spiess","farben":["#8b3a1a","#d9822b","#f2c14e"],"schlagworte":["Straßenessen","Grillen","Erdnuss","Nigeria"],"vegetarisch_moeglich":false},{"id":"westafrika-puff-puff","name":"Puff-Puff – goldene Hefebällchen","originalname":"Puff-Puff","kueche":"westafrika","region":"Nigeria (in ganz Westafrika verbreitet)","beliebtheit":80,"hauptkategorie":"suess","fleischsorte":"","fischsorte":"","gang":"gebaeck","kurz":"Weiche, luftige Hefebällchen aus dem heißen Öl: außen knusprig-golden, innen fluffig, nach Muskat duftend.","hintergrund":"Puff-Puff ist ein frittiertes Hefegebäck, das in ganz Westafrika zu Hause ist – unter Dutzenden Namen: In Ghana heißt es Bofrot, in Kamerun und Senegal Beignet, in Guinea Gato. Der Name Puff-Puff stammt aus Nigeria und beschreibt, wie der Teig im Öl aufbläht. Man isst es als Straßensnack, auf Hochzeiten und Geburtstagen, manchmal zum Frühstück. Gewürzt wird meist mit Muskat, gern auch mit Vanille oder Zimt, außen wälzt man die Bällchen in Zucker.","portionen":4,"zeit":{"vorbereitung":20,"garen":20,"ruhen":60},"schwierigkeit":1,"zutaten":[{"gruppe":"Teig","liste":[{"menge":300,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"gesiebt"},{"menge":7,"einheit":"g","name":"Trockenhefe (1 Päckchen)","hinweis":""},{"menge":60,"einheit":"g","name":"Zucker","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"frisch geriebene Muskatnuss","hinweis":"ganze Nuss reiben – Pulver verliert schnell Duft"},{"menge":300,"einheit":"ml","name":"lauwarmes Wasser","hinweis":"ca. 35 °C, nicht heißer, sonst stirbt die Hefe"},{"menge":1,"einheit":"TL","name":"Vanillezucker","hinweis":"optional"}]},{"gruppe":"Zum Frittieren und Wälzen","liste":[{"menge":1,"einheit":"l","name":"neutrales Frittieröl","hinweis":"Raps- oder Erdnussöl; Topf höchstens zu einem Drittel füllen"},{"menge":3,"einheit":"EL","name":"Zucker","hinweis":"zum Wälzen, optional mit 1/2 TL Zimt gemischt"}]}],"ausruestung":["große Rührschüssel","Holzlöffel oder Handrührgerät mit Knethaken","hoher, schwerer Topf oder Fritteuse","Küchenthermometer","Schaumlöffel","Küchenpapier","kleiner Eisportionierer oder zwei Esslöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehl, Zucker, Hefe und Salz ab und siebe das Mehl in eine große Schüssel; das Sieben lüftet das Mehl und beugt Klümpchen vor. Reibe die Muskatnuss frisch. Stelle das Wasser auf lauwarme 35 °C ein – es soll sich an der Handinnenfläche kaum warm anfühlen. Hole Frittieröl, Thermometer, Schaumlöffel und einen mit Küchenpapier ausgelegten Teller bereit, denn wenn die Bällchen goldbraun sind, geht es schnell.","dauer":10,"tipp":""},{"titel":"Teig anrühren","aktion":"mischen","text":"Vermische Mehl, Hefe, Zucker, Salz und Muskat trocken in der Schüssel und gieße das Wasser nach und nach hinein. Rühre mit einem Holzlöffel kräftig 3–4 Minuten, bis ein glatter, zähflüssiger Teig entsteht, der in dicken Bändern vom Löffel reißt – dicker als Pfannkuchenteig, aber viel weicher als Brotteig. Ist er zu fest, gib esslöffelweise Wasser zu, ist er zu dünn, einen Löffel Mehl. Der Teig muss sich nachher mit der Hand leicht vom Daumen abstreifen lassen.","dauer":8,"tipp":"Rühre kräftig und lange: Dadurch bildet sich Gluten, und der Teig trägt später die Gasbläschen."},{"titel":"Teig gehen lassen","aktion":"gehen","text":"Decke die Schüssel mit einem feuchten Tuch oder Frischhaltefolie ab und stelle sie an einen warmen Ort (ca. 26–30 °C), etwa in den Backofen mit eingeschalteter Lampe. Lass den Teig 60–75 Minuten gehen, bis sich sein Volumen verdoppelt hat, die Oberfläche voller kleiner Bläschen ist und der Teig leicht säuerlich-hefig riecht. Beim Hineinstechen sinkt er nicht gleich zusammen. Zu kurzes Gehen macht schwere, ölige Bällchen, zu langes gibt sauren Geschmack.","dauer":70,"tipp":""},{"titel":"Teig durchschlagen","aktion":"aufschlagen","text":"Rühre den aufgegangenen Teig mit dem Holzlöffel oder der Hand 1–2 Minuten kräftig durch. Dabei entweicht ein Teil des Gases, der Teig wird glatter und elastischer, und die Blasen verteilen sich gleichmäßiger. Er soll schwer, glänzend und fadenziehend vom Löffel fallen. Dieser Schritt entscheidet, ob die Bällchen innen gleichmäßig luftig oder mit großen Löchern ausfallen.","dauer":3,"tipp":""},{"titel":"Öl erhitzen","aktion":"frittieren","text":"Fülle das Öl in den Topf, höchstens ein Drittel hoch, und erhitze es bei mittlerer Hitze auf 170–175 °C. Ohne Thermometer hältst du einen Holzlöffelstiel hinein: Steigen sofort viele kleine Bläschen auf, ist die Temperatur richtig. Gib einen Teelöffel Teig als Test ins Öl: Er soll nach 10 Sekunden aufsteigen und leicht Farbe annehmen. Ist das Öl zu heiß, werden die Bällchen außen dunkel und innen roh, bei zu wenig Hitze saugen sie sich mit Fett voll.","dauer":8,"tipp":""},{"titel":"Bällchen portionieren und frittieren","aktion":"frittieren","text":"Nimm mit nassen Händen eine Portion Teig und drücke sie durch den Ring aus Daumen und Zeigefinger, sodass ein walnussgroßes Bällchen entsteht, oder benutze einen Eisportionierer. Lass es vorsichtig ins Öl gleiten und arbeite in Chargen von 6–8 Stück, damit die Temperatur stabil bleibt. Die Bällchen gehen unter, steigen auf und wenden sich oft von selbst. Wende sie nach 2 Minuten, wenn die Unterseite goldbraun ist, und frittiere weitere 2–3 Minuten. Sie sind fertig, wenn sie rundum tief goldbraun sind und hohl klingen, wenn du leicht draufklopfst.","dauer":15,"tipp":"Zeigt das Aufschneiden ein klebriges Innere, war das Öl zu heiß oder die Bällchen zu groß: Nächste Charge kleiner formen."},{"titel":"Abtropfen und wälzen","aktion":"anrichten","text":"Hebe die fertigen Bällchen mit dem Schaumlöffel heraus und lasse sie 30 Sekunden auf Küchenpapier abtropfen. Wälze sie noch warm in Zucker – der haftet am dünnen Ölfilm –, optional mit Zimt gemischt. Beim Anschneiden soll innen ein luftiges, feinporiges Netz sichtbar sein und der Duft nach Muskat und Hefe aufsteigen. Puff-Puff schmeckt warm am besten, nach etwa einer Stunde verlieren sie ihre Knusprigkeit.","dauer":5,"tipp":""}],"profitipps":["Ölstand und Temperatur machen den Unterschied: Mit Thermometer arbeiten und zwischen den Chargen auf 170 °C zurückheizen lassen.","Lauwarmes Wasser ist ein Muss – zu kaltes Wasser verzögert die Hefe, zu heißes tötet sie.","Ein Teig, der sich mit der Hand abstreifen lässt, ergibt die klassische runde Form; ein zu steifer Teig wird dicht.","Sprudelnder Teig bleibt nicht lange: Nach dem Gehen zügig frittieren, sonst fällt er zusammen.","Frisch geriebene Muskatnuss ist das Aroma, an dem man Puff-Puff erkennt."],"varianten":["Mit Hibiskuspulver und Hibiskussirup – die britisch-nigerianische Köchin Lopè Ariyo serviert so ihre Version.","Mit Bananenpüree im Teig (Banana Puff-Puff).","Als herzhafte Variante mit Chili und gehackter Zwiebel im Teig, dazu scharfe Pfeffersauce.","In Ghana als Bofrot, in Senegal als Beignet mit Hirsemehl."],"beilagen":["Hibiskussirup","Fruchtdip aus Erdbeeren oder Himbeeren","Schokoladensauce"],"getraenk":"Gekühlter Hibiskustee (Zobo), Ingwertee oder Kaffee","koeche":[{"name":"Lopè Ariyo","bezug":"Die britisch-nigerianische Köchin serviert in ihrem Buch „Hibiscus“ eine Puff-Puff-Version mit gemahlenen Hibiskusblüten und Hibiskussirup.","quelle":"https://creators.vice.com/en/article/zmbjb9/meet-the-hibiscus-obsessed-chef-celebrating-british-nigerian-food"}],"quellen":[{"titel":"Wikipedia – Puff-puff","url":"https://en.wikipedia.org/wiki/Puff-puff"},{"titel":"VICE – Meet the hibiscus-obsessed chef celebrating British-Nigerian food","url":"https://creators.vice.com/en/article/zmbjb9/meet-the-hibiscus-obsessed-chef-celebrating-british-nigerian-food"}],"bild":"gebaeck","farben":["#c8842a","#e8b04a","#fff1d6"],"schlagworte":["Straßensnack","Hefeteig","Party","Frittiertes"],"themen":["streetfood"],"vegetarisch_moeglich":true},{"id":"westafrika-poulet-yassa","name":"Poulet Yassa","originalname":"Yassa Ginaar","kueche":"westafrika","region":"Senegal","beliebtheit":78,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Mariniertes Hähnchen mit Bergen von sanft geschmorten Zwiebeln, Zitrone und Senf – säuerlich, süß und feurig.","hintergrund":"Poulet Yassa stammt aus der Casamance, der südlichen Region Senegals, und wird in ganz Westafrika zubereitet. Charakteristisch sind sehr viel Zwiebel, frischer Zitronensaft, Senf und Scotch-Bonnet-Chili. Das Hähnchen wird mariniert, auf dem Grill oder in der Pfanne angebraten und anschließend in der Zwiebelmarinade geschmort. Serviert wird es auf weißem Reis. Pierre Thiam, der senegalesische Küchenchef und Autor, hat die senegalesische Küche in Büchern und Restaurants international bekannt gemacht.","portionen":4,"zeit":{"vorbereitung":30,"garen":60,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Marinade","liste":[{"menge":8,"einheit":"Stück","name":"Hähnchenschenkel und -keulen","hinweis":"bone-in, ca. 1,3 kg"},{"menge":6,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in dünne Halbringe, ca. 1 kg"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":120,"einheit":"ml","name":"Zitronensaft","hinweis":"frisch gepresst (ca. 4 Zitronen)"},{"menge":3,"einheit":"EL","name":"Dijon-Senf","hinweis":""},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet oder 2 rote Chilis","hinweis":"ganz oder gehackt"},{"menge":3,"einheit":"EL","name":"Erdnuss- oder Pflanzenöl","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Essig","hinweis":"optional"}]},{"gruppe":"Zum Schmoren","liste":[{"menge":200,"einheit":"ml","name":"Hühnerbrühe oder Wasser","hinweis":""},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":100,"einheit":"g","name":"grüne Oliven","hinweis":"optional"}]},{"gruppe":"Zum Servieren","liste":[{"menge":300,"einheit":"g","name":"Langkornreis","hinweis":""}]}],"ausruestung":["große Schüssel","Schmortopf mit Deckel","Pfanne oder Grill"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schäle die Zwiebeln und schneide sie in dünne Halbringe (ca. 2–3 mm); das sind viele, aber sie schmelzen später fast zu einer Sauce. Presse die Zitronen aus, hacke den Knoblauch und teile die Chili. Lege Hähnchenteile auf Küchenpapier und tupfe sie trocken, damit sie später besser bräunen. Lege Reis, Senf und Öl bereit.","dauer":20,"tipp":""},{"titel":"Hähnchen marinieren","aktion":"marinieren","text":"Vermenge in einer großen Schüssel Zwiebeln, Knoblauch, Zitronensaft, Senf, Öl, Lorbeer, Pfeffer, Salz, Chili und optional Essig. Lege das Hähnchen hinein und massiere die Marinade ein, bis alles bedeckt ist. Decke die Schüssel ab und lasse es mindestens 4 Stunden, besser über Nacht im Kühlschrank ziehen. Die Säure macht das Fleisch zart und die Zwiebeln milder.","dauer":240,"tipp":""},{"titel":"Hähnchen herausnehmen","aktion":"vorbereiten","text":"Hebe das Hähnchen aus der Marinade und streife die Zwiebeln ab; sie bleiben in der Schüssel. Tupfe das Fleisch gut trocken, denn nasses Fleisch dämpft und bräunt nicht. Fange die Marinade samt Zwiebeln auf, du brauchst sie gleich. Heize eine Grillpfanne oder den Grill auf mittelhohe Hitze. Entferne dabei auch Knoblauchstücke und Chilireste von der Haut, denn sie verbrennen beim Braten und schmecken bitter. Die Zwiebeln dürfen auf keinen Fall in die Pfanne kommen, sie sind für den späteren Schmorgang reserviert.","dauer":10,"tipp":""},{"titel":"Hähnchen anbraten","aktion":"anbraten","text":"Erhitze 2 EL Öl in einer großen Pfanne und brate die Hähnchenteile 4–5 Minuten pro Seite, bis sie tief goldbraun sind. Lege sie dabei nur in einer Schicht ein, damit sie braten statt dämpfen. Das Fleisch muss nicht gar sein, es gart später in der Zwiebelsauce. Alternativ kannst du es 10 Minuten bei 220 °C im Ofen vorgrillen.","dauer":12,"tipp":"Die Röstaromen im Bratensatz gehören mit in die Zwiebelsauce."},{"titel":"Zwiebeln dünsten","aktion":"schmoren","text":"Gib die Zwiebeln aus der Marinade in den Schmortopf und dünste sie 10–15 Minuten bei mittlerer Hitze, ohne dass sie braun werden. Sie sollen weich, glasig und süßlich duften. Gieße etwas Marinade und Brühe zu, damit sie nicht anlegen. Dieser Schritt macht die Sauce aus. Rühre häufig und achte auf das Geräusch: ein leises Zischen ist richtig, lautes Spritzen bedeutet zu hohe Hitze. Wenn die Zwiebeln zu bräunen beginnen, gib einen Schuss Brühe hinzu und reduziere die Hitze, denn die Sauce soll hell und mild-süß bleiben.","dauer":15,"tipp":""},{"titel":"Schmoren","aktion":"schmoren","text":"Lege das angebratene Hähnchen auf die Zwiebeln, gieße die restliche Marinade und Brühe dazu und bringe alles zum Köcheln. Decke ab und schmore bei niedriger Hitze 35–40 Minuten, bis das Fleisch zart ist und die Zwiebeln fast zu Sauce zerfallen. Wende die Teile nach 20 Minuten. Der Deckel hält den Dampf im Topf, so bleibt das Fleisch saftig. Prüfe nach 30 Minuten, ob die Flüssigkeit noch reicht: Sie soll das Fleisch etwa zu einem Drittel umgeben. Die Zwiebeln werden dabei glasig-golden und beginnen zu zerfallen, ein sicheres Zeichen, dass die Sauce reif wird.","dauer":40,"tipp":""},{"titel":"Reis kochen","aktion":"kochen","text":"Spüle den Reis, gib ihn in einen Topf mit der 1,5-fachen Menge Wasser und einer Prise Salz, koche ihn auf, decke ab und lasse ihn auf kleinster Hitze 12–15 Minuten quellen. Dann 5 Minuten ruhen lassen und mit der Gabel auflockern. Der Reis nimmt später die säuerlich-würzige Sauce auf. Rühre nach dem Aufkochen nicht mehr um, sonst wird der Reis klebrig. Wenn du magst, gib einen Teelöffel Öl ins Wasser, das macht die Körner lockerer. Probiere ein Korn: Es soll weich, aber nicht matschig sein und keinen harten Kern mehr haben.","dauer":20,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Sauce: Sie soll säuerlich-frisch von Zitrone, süß von den Zwiebeln, würzig-scharf von Chili und leicht senfig schmecken. Fehlt Säure, gib einen Spritzer Zitronensaft zu; ist sie zu sauer, ein Löffel Zucker. Prüfe, ob das Fleisch gar ist (80–85 °C Kerntemperatur). Gib nach Wunsch Oliven dazu und lasse sie 5 Minuten mitgaren.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Gib den Reis auf Teller, lege Hähnchen darauf und überziehe es großzügig mit den Zwiebeln und der Sauce. Serviere dazu Zitronenspalten und scharfe Soße. Das Gericht schmeckt am nächsten Tag noch besser, wenn die Zwiebeln durchgezogen sind. Reiche zusätzlich frische Chilischoten oder eine scharfe Paste, damit jeder selbst nachschärfen kann, und stelle Zitronenspalten in die Mitte. Traditionell isst man das Gericht aus einer gemeinsamen Schüssel, Brot oder Baguette dient zum Aufnehmen der Zwiebelsauce.","dauer":0,"tipp":""}],"profitipps":["Mindestens 4 Stunden marinieren, besser über Nacht.","Hähnchen vor dem Schmoren anbraten – das gibt Röstaroma.","Zwiebeln langsam dünsten, nicht bräunen.","Viel Zwiebel, viel Zitrone, Senf – das Dreieck der Yassa.","Chili ganz lassen, wenn du es milder magst."],"varianten":["Yassa mit Fisch (Yassa Guinaar)","Mit Oliven und Karotten","Yassa mit Lamm"],"beilagen":["Weißer Reis","Zitronenspalten","scharfe Sauce"],"getraenk":"Bissap (Hibiskus) oder ein trockener Weißwein","koeche":[{"name":"Pierre Thiam","bezug":"Der senegalesische Küchenchef und Autor hat mit seinem Buch „Senegal“ und der Küche seines Heimatlandes Senegals Gerichte wie Yassa und Mafé international bekannt gemacht.","quelle":"https://www.simonandschuster.ca/books/Senegal/Pierre-Thiam/9781891105555"}],"quellen":[{"titel":"Simon & Schuster – Senegal (Pierre Thiam)","url":"https://www.simonandschuster.ca/books/Senegal/Pierre-Thiam/9781891105555"},{"titel":"Saveur – The Flavors of Senegal (Pierre Thiam)","url":"https://www.saveur.com/article/Kitchen/Senegal-Pierre-Thiam"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"}],"bild":"haehnchen","farben":["#e5b83a","#a85a1f","#f2e2a0"],"schlagworte":["Senegal","Zwiebeln","Zitrone","Casamance"],"vegetarisch_moeglich":false},{"id":"westafrika-kelewele","name":"Kelewele – gewürzte Kochbananen aus Ghana","originalname":"Kelewele","kueche":"westafrika","region":"Ghana (Accra)","beliebtheit":78,"hauptkategorie":"vegan","fleischsorte":"","fischsorte":"","gang":"snack","kurz":"Sehr reife Kochbananen, mit Ingwer, Chili und Nelken gewürzt und goldbraun frittiert – süß, scharf und knusprig zugleich.","hintergrund":"Kelewele ist ein Ghana-Klassiker für den Abend: In Accra verkaufen Straßenhändler die gewürzten, frittierten Kochbananenwürfel meist abends, auf dem Land oft schon nachmittags. Das Wort bezeichnet sowohl das Gericht als auch die Gewürzmischung aus Ingwer, Cayennepfeffer und Salz, die je nach Haushalt mit Nelken, Anis, Muskat oder Zwiebel ergänzt wird. Gegessen wird es als Snack, zu Erdnüssen, als Beilage zu Bohnengerichten wie Red Red oder Waakye – oder einfach so, als Dessert.","portionen":4,"zeit":{"vorbereitung":20,"garen":15,"ruhen":20},"schwierigkeit":1,"zutaten":[{"gruppe":"Kochbananen","liste":[{"menge":4,"einheit":"Stück","name":"sehr reife Kochbananen","hinweis":"gelb mit vielen schwarzen Flecken, noch fest; Afroshop oder gut sortierter Supermarkt (Plantains)"},{"menge":750,"einheit":"ml","name":"Frittieröl","hinweis":"Erdnuss- oder Rapsöl; traditionell auch Palmöl"}]},{"gruppe":"Gewürzpaste","liste":[{"menge":1,"einheit":"Stück","name":"Ingwerstück (ca. 4 cm)","hinweis":"frisch, geschält"},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel oder Schalotte","hinweis":""},{"menge":1,"einheit":"TL","name":"Cayennepfeffer","hinweis":"nach Schärfe 1/2 bis 2 TL"},{"menge":1,"einheit":"Msp.","name":"gemahlene Nelken","hinweis":""},{"menge":0.5,"einheit":"TL","name":"gemahlener Anis","hinweis":"optional"},{"menge":1,"einheit":"Prise","name":"frisch geriebene Muskatnuss","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Limettensaft","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":100,"einheit":"g","name":"geröstete, gesalzene Erdnüsse","hinweis":"klassisch dazu"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"optional"}]}],"ausruestung":["hoher Topf oder Pfanne mit hohem Rand","Küchenthermometer","Mörser oder Mixer","Schaumlöffel","Küchenpapier"],"schritte":[{"titel":"Reife der Kochbananen prüfen","aktion":"vorbereiten","text":"Wähle Kochbananen, deren Schale größtenteils schwarz oder stark gefleckt ist; sie fühlen sich leicht nachgiebig an wie reife Avocados und duften süß. Grüne oder rein gelbe Exemplare sind zu stärkehaltig und schmecken beim Frittieren mehlig statt karamellig. Fehlt dir reife Ware, lege die Bananen in einen Papierbeutel an einen warmen Platz, bis sie nachreifen – das dauert 3–5 Tage. Schneide Ingwer, Knoblauch und Zwiebel grob, damit sie nachher leichter zu mahlen sind.","dauer":5,"tipp":""},{"titel":"Bananen schälen","aktion":"schneiden","text":"Schneide beide Enden der Kochbananen ab und ritze die Schale einmal längs ein, ohne tief ins Fruchtfleisch zu schneiden. Löse die Schale mit dem Daumen; reife Plantains sind weicher als Bananen, die Schale haftet jedoch etwas fester. Die Frucht darf beim Schälen nicht matschig werden – ist sie es, sind die Bananen überreif und fallen beim Frittieren auseinander. Lege die geschälten Bananen auf ein Brett und prüfe sie auf braune, ungenießbare Stellen.","dauer":5,"tipp":""},{"titel":"Würfel schneiden","aktion":"schneiden","text":"Schneide jede Banane quer in 2 cm dicke Würfel, etwa 2 × 2 × 2 cm. Gleich große Würfel garen gleichmäßig und karamellisieren zur selben Zeit. Zu dünne Stücke werden trocken, zu große bleiben innen stärkig. Gib die Würfel in eine Schüssel; sie dürfen nicht lange offen stehen, sonst oxidieren sie und verfärben sich. Wenn nötig, träufelst du etwas Limettensaft darüber.","dauer":5,"tipp":""},{"titel":"Gewürzpaste mahlen","aktion":"mischen","text":"Zerstoße Ingwer, Knoblauch und Zwiebel im Mörser oder püriere sie im kleinen Mixer mit 1 EL Wasser zu einer feinen, feuchten Paste. Rühre Cayenne, Nelken, Anis, Muskat, Salz und Limettensaft ein. Die Mischung soll scharf-würzig riechen, mit einer süßen Note von Nelke und Anis. Koste mit der Fingerspitze: Sie darf ruhig kräftig sein, denn die Süße der Bananen mildert sie später stark ab.","dauer":5,"tipp":""},{"titel":"Marinieren","aktion":"marinieren","text":"Vermenge die Bananenwürfel mit der Paste, bis jedes Stück rundum gefärbt ist, und lasse alles 15–20 Minuten bei Zimmertemperatur ziehen. Die Salzlake und die Zwiebelsäfte ziehen etwas Wasser aus der Oberfläche, wodurch sie später knuspriger bräunt. Länger als 30 Minuten solltest du nicht warten, sonst werden die Würfel weich. Die Paste soll gleichmäßig haften; tupfe überschüssige Flüssigkeit in der Schüssel nicht ab, sie wird beim Frittieren zu einer würzigen Kruste.","dauer":20,"tipp":""},{"titel":"Öl erhitzen","aktion":"frittieren","text":"Erhitze das Öl in einem hohen Topf auf 170–175 °C. Es soll mindestens 3–4 cm hoch stehen, der Topf aber höchstens zur Hälfte gefüllt sein. Ohne Thermometer hältst du einen Holzlöffelstiel hinein: Steigen sofort feine Bläschen auf, passt die Temperatur. Zu kühles Öl macht die Würfel fettig, zu heißes verbrennt die Paste, bevor die Banane weich ist. Halte Küchenpapier und einen Schaumlöffel bereit.","dauer":8,"tipp":""},{"titel":"In Chargen frittieren","aktion":"frittieren","text":"Gib die Würfel in zwei oder drei Chargen ins Öl, sodass sie nicht aneinanderkleben und die Temperatur nicht abfällt. Frittiere sie 3–4 Minuten und wende sie gelegentlich. Sie sind fertig, wenn die Ränder dunkel karamellisieren, die Kruste knistert und die Würfel nach gebratener Banane und Gewürzen duften. Sehr reife Plantains bräunen schnell, behalte sie im Auge; schwarze Ränder bedeuten, dass sie zu weit sind.","dauer":12,"tipp":"Das Aroma wird besser, wenn die Würzpaste am Rand fast schwarz-braun wird – aber nicht verbrennt."},{"titel":"Abtropfen und servieren","aktion":"anrichten","text":"Hebe die Würfel mit dem Schaumlöffel heraus und lasse sie 1–2 Minuten auf Küchenpapier abtropfen. Streue sie noch heiß mit wenig Salz und Limettensaft und serviere sie sofort in einer Schüssel mit gerösteten Erdnüssen. Kelewele schmeckt süß, scharf, würzig und leicht knusprig außen; innen ist es cremig-weich. Kalt oder aufgewärmt verliert es seine Kruste, daher am besten frisch essen.","dauer":3,"tipp":""}],"profitipps":["Entscheidend ist die Reife: je schwärzer die Schale, desto süßer und karamelliger das Ergebnis.","Nicht zu viele Würfel auf einmal ins Öl geben, sonst kocht die Banane im Öl statt zu bräunen.","Die Gewürze lassen sich gut vorbereiten: Die Paste hält abgedeckt 2 Tage im Kühlschrank.","Ob du Zwiebel in die Paste gibst oder nicht, ist Geschmackssache – ohne Zwiebel wird sie milder und süßer.","Wer nicht frittieren möchte, kann die Würfel mit etwas Öl bei 220 °C Ober-/Unterhitze (200 °C Umluft) 20 Minuten im Ofen rösten, die Kruste fällt dann zarter aus."],"varianten":["Mit gerösteten Erdnüssen als klassischer Abendsnack.","Als Beilage zu Red Red (Bohneneintopf in Palmöl) oder zu Waakye.","Mit Chili-Limetten-Salz bestreut als Biersnack.","Süße Variante ohne Zwiebel mit mehr Ingwer und Zimt, als Dessert mit Vanilleeis."],"beilagen":["geröstete Erdnüsse","Shito oder scharfe Pfeffersauce","Red Red (Bohneneintopf)"],"getraenk":"Kaltes Ingwerbier, Malzbier (Malta) oder ein kühles Lagerbier","koeche":[{"name":"Zoe Adjonyoh","bezug":"Die britisch-ghanaische Köchin empfiehlt in ihrem Waakye-Reis-Rezept ausdrücklich Kelewele als passende Beilage.","quelle":"https://www.nigella.com/recipes/guests/zoe-adjonyohs-waakye-rice"}],"quellen":[{"titel":"Wikipedia – Kelewele","url":"https://en.wikipedia.org/wiki/Kelewele"},{"titel":"Nigella.com – Zoe Adjonyoh's Waakye Rice","url":"https://www.nigella.com/recipes/guests/zoe-adjonyohs-waakye-rice"},{"titel":"Tasting Table – 12 Traditional West African Dishes","url":"https://www.tastingtable.com/1216347/traditional-west-african-dishes-you-need-to-try-at-least-once/"}],"bild":"pfanne","farben":["#8b4513","#d98c2b","#f5d9a0"],"schlagworte":["Straßensnack","vegan","Kochbanane","Abendsnack"],"themen":["streetfood"],"vegetarisch_moeglich":true},{"id":"westafrika-egusi-suppe","name":"Egusi-Suppe mit Spinat","originalname":"Egusi Soup","kueche":"westafrika","region":"Nigeria","beliebtheit":76,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Sämige Suppe aus gemahlenen Kürbiskernen, Palmöl, Spinat und Fleisch, mit Fufu oder Eba serviert.","hintergrund":"Egusi-Suppe ist eines der meistgegessenen Gerichte Nigerias und steht in den TasteAtlas-Listen für Nigeria an der Spitze. Egusi sind die Kerne einer Melonenart (Colocynthis citrullus), die geröstet und gemahlen werden und der Suppe eine nussige, körnig-cremige Textur geben. Dazu kommen Palmöl, Zwiebeln, Chili, getrockneter Fisch oder Krabbenpulver, Fleisch und Blattgemüse wie Spinat oder Bitterblatt. Man isst sie mit Fufu, Eba oder Pounded Yam, mit den Fingern.","portionen":6,"zeit":{"vorbereitung":30,"garen":70,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Brühe","liste":[{"menge":600,"einheit":"g","name":"Rindfleisch (Schulter), gewürfelt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"gehackt"},{"menge":2,"einheit":"Stück","name":"Brühwürfel","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"l","name":"Wasser","hinweis":""},{"menge":50,"einheit":"g","name":"getrockneter Fisch oder Stockfisch","hinweis":"optional; im Afro-Laden"}]},{"gruppe":"Suppe","liste":[{"menge":250,"einheit":"g","name":"Egusi (gemahlene Melonenkerne)","hinweis":"im Afro-Laden; Ersatz: gemahlene Kürbiskerne"},{"menge":150,"einheit":"ml","name":"rotes Palmöl","hinweis":"Ersatz: Erdnussöl mit Paprikapulver"},{"menge":1,"einheit":"Stück","name":"große Zwiebel","hinweis":"fein gehackt"},{"menge":3,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet","hinweis":"nach Schärfe"},{"menge":1,"einheit":"EL","name":"Krabbenpulver oder Fischsauce","hinweis":"optional"},{"menge":400,"einheit":"g","name":"frischer Spinat","hinweis":"gewaschen, grob gehackt"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf","Mixer","Holzlöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Würfle das Fleisch in 3 cm große Stücke, hacke die Zwiebeln fein und wasche den Spinat gründlich. Entferne die Stiele des Spinats, wenn sie zäh sind, und schneide ihn grob. Mixe die Scotch Bonnet mit etwas Wasser zu einer Paste, damit sich die Schärfe gleichmäßig verteilt. Lege Egusi und Palmöl bereit.","dauer":15,"tipp":""},{"titel":"Fleisch kochen","aktion":"kochen","text":"Koche das Rindfleisch in einem Topf mit Zwiebel, Brühwürfeln, Salz und 1 Liter Wasser 40–45 Minuten bei mittlerer Hitze, bis es zart ist. Gib getrockneten Fisch dazu, wenn du ihn verwendest. Die entstehende Brühe ist die Basis der Suppe; schöpfe sie nicht ab, sondern bewahre sie komplett auf. Schäume das Fleisch in den ersten Minuten ab, damit die Brühe klar und sauber schmeckt. Prüfe die Zartheit mit einer Gabel: Sie soll ohne Widerstand eindringen. Wenn das Fleisch noch zäh ist, koche weitere 15 Minuten und gieße etwas Wasser nach.","dauer":45,"tipp":""},{"titel":"Palmöl erhitzen","aktion":"anbraten","text":"Erhitze das Palmöl in einem zweiten, großen Topf bei mittlerer Hitze, bis es schmilzt und leicht raucht (ca. 2 Minuten). Gib die Zwiebel hinein und brate sie 4–5 Minuten, bis sie glasig ist. Rühre das Tomatenmark ein und brate es 3 Minuten, bis es dunkelrot wird. Das Palmöl gibt der Suppe ihre rötliche Farbe und nussigen Geschmack.","dauer":10,"tipp":"Palmöl nicht überhitzen – es wird bitter."},{"titel":"Egusi einrühren","aktion":"mischen","text":"Vermische Egusi mit etwas Brühe zu einer dicken Paste und gib sie klecksweise in das heiße Öl. Rühre vorsichtig und lasse die Egusi 5–8 Minuten ohne Rühren stocken, so bilden sich körnige Klumpen. Wende die Klumpen einmal. So entsteht die typische Textur. Wenn die Paste zu trocken ist, gib einen kleinen Schuss Brühe dazu, bis sie wie dicker Brei wirkt. Sie soll zischend im Fett stocken und dabei eine hellgelbe bis goldbraune Färbung annehmen. Nicht ständig rühren: Erst das Stocken bildet die körnigen Klumpen, die Egusi-Suppe so besonders machen.","dauer":8,"tipp":""},{"titel":"Brühe angießen","aktion":"koecheln","text":"Gieße die heiße Fleischbrühe nach und nach zu den Egusi, rühre sanft um und gib das gekochte Fleisch hinein. Lasse alles 15–20 Minuten leise köcheln, bis die Suppe sämig und das Öl oben schwimmt. Rühre häufig, damit nichts am Boden anbrennt. Gieße die Brühe in mehreren Portionen zu, damit die Egusi-Klumpen nicht zerfallen. Die Suppe wird beim Köcheln dicker und das Palmöl steigt in einer leuchtend roten Schicht an die Oberfläche, ein Zeichen für gute Qualität. Rühre vom Rand zur Mitte, nie kräftig im Kreis.","dauer":20,"tipp":""},{"titel":"Würzen","aktion":"abschmecken","text":"Rühre die Chilipaste, Krabbenpulver oder Fischsauce hinein und schmecke die Suppe mit Salz ab. Sie soll kräftig, leicht scharf und nussig-erdig schmecken. Wenn die Suppe zu dick ist, gib heißes Wasser dazu. Probiere unbedingt mit etwas Abstand zum Herd: Zu heiße Löffel betäuben den Geschmack. Die Suppe soll nussig, würzig und leicht scharf schmecken, mit einer feinen Salznote vom Fisch. Wenn sie flach schmeckt, hilft eine weitere Prise Krabbenpulver, nicht mehr Salz.","dauer":3,"tipp":""},{"titel":"Spinat zugeben","aktion":"mischen","text":"Gib den Spinat in die Suppe und rühre ihn unter, damit er zusammenfällt. Koche ihn nur 3–5 Minuten, damit er seine grüne Farbe und etwas Biss behält. Zu langes Kochen macht ihn matschig und grau. Der Spinat fällt innerhalb von Sekunden zusammen und gibt dabei Wasser ab, daher bleibt die Suppe nicht zu dick. Wenn du kräftigeres Blattgemüse wie Bitterblatt oder Grünkohl verwendest, koche es 10 Minuten, bis es weich ist. Rühre den Spinat nur kurz unter, damit die Farbe frisch bleibt.","dauer":5,"tipp":""},{"titel":"Ruhen","aktion":"ruhen","text":"Nimm den Topf vom Herd und lasse die Suppe 5 Minuten ziehen. Die Aromen verbinden sich, das Öl setzt sich oben ab. Schmecke nochmals ab. Gerade bei Suppen mit Palmöl lohnt sich dieses kurze Ruhen: Das Öl setzt sich oben ab, die Egusi-Klumpen nehmen Geschmack auf und die Suppe wirkt runder. Prüfe die Konsistenz: Sie soll sämig sein, aber noch fließen, und mit einer leichten Ölschicht überzogen.","dauer":5,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Schöpfe die Suppe in tiefe Schalen und serviere sie heiß mit Fufu, Eba oder Pounded Yam. Man formt mit den Fingern der rechten Hand ein Kügelchen aus dem Fufu, tunkt es in die Suppe und isst es ohne zu kauen. Alternativ passt Reis. Wenn du kein Fufu bekommst, funktioniert auch Reis, Yams-Pulver (Poundo Yam) oder fester Maisbrei. Reiche ein Schälchen Wasser zum Händewaschen, denn gegessen wird traditionell ohne Besteck. Reste halten im Kühlschrank 3 Tage und werden beim Erwärmen dicker, gieße dann etwas Wasser nach.","dauer":0,"tipp":""}],"profitipps":["Egusi nicht rühren, sondern klumpig stocken lassen.","Palmöl nicht rauchig überhitzen.","Spinat erst am Schluss, damit er grün bleibt.","Fleischbrühe als Basis nutzen – nicht mit Wasser verdünnen.","Vegetarisch geht es mit Pilzen und Gemüsebrühe."],"varianten":["Mit Bitterblatt (Ugu)","Mit Fisch und Garnelen","Vegetarisch mit Pilzen"],"beilagen":["Fufu","Eba","Pounded Yam"],"getraenk":"Malzbier oder kaltes Wasser","koeche":[],"quellen":[{"titel":"TasteAtlas – Best Rated Dishes in Nigeria","url":"https://www.tasteatlas.com/best-rated-dishes-in-nigeria"},{"titel":"Saiga Tours – Must-Try Foods in Nigeria","url":"https://www.saigatours.com/article/8-must-try-foods-in-nigeria"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"}],"bild":"suppe","farben":["#b8541a","#8a9a3a","#e8c07a"],"schlagworte":["Nigeria","Suppe","Egusi","Palmöl"],"vegetarisch_moeglich":true},{"id":"westafrika-waakye","name":"Waakye – Reis mit Schwarzaugenbohnen aus Ghana","originalname":"Waakye","kueche":"westafrika","region":"Ghana","beliebtheit":76,"hauptkategorie":"vegetarisch","fleischsorte":"","fischsorte":"","gang":"hauptgericht","kurz":"Rotbrauner Reis mit Schwarzaugenbohnen, gekocht in aromatischem Blätterwasser und serviert mit Ei, Shito, Salat und gebratenen Kochbananen.","hintergrund":"Waakye stammt aus dem Norden Ghanas und kam über Händler in die Städte des Südens; heute wird es in Accra morgens und mittags an jeder Ecke verkauft, oft in Bananenblättern eingeschlagen. Der Name kommt aus dem Dagbani und bezeichnet eine Bohnensorte. Rot wird der Reis durch getrocknete Blattscheiden der Sorghum-Hirse, die im Kochwasser gekocht werden. Dazu gehören traditionell scharfe Pfeffersauce Shito, Kohlsalat, gekochte Eier, Gari und Kochbananen.","portionen":4,"zeit":{"vorbereitung":25,"garen":90,"ruhen":480},"schwierigkeit":2,"zutaten":[{"gruppe":"Reis und Bohnen","liste":[{"menge":250,"einheit":"g","name":"getrocknete Schwarzaugenbohnen","hinweis":"über Nacht einweichen; gibt es im Supermarkt, Bioladen oder Afroshop"},{"menge":400,"einheit":"g","name":"Langkornreis (Parboiled)","hinweis":"bleibt körnig"},{"menge":4,"einheit":"Stück","name":"getrocknete Sorghum-Blattscheiden (Waakye-Blätter)","hinweis":"Afroshop; Ersatz: 1 TL Natron, gibt Farbe, aber etwas milder"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"geviertelt"},{"menge":1,"einheit":"Stück","name":"milde rote Chilischote","hinweis":"ganz"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"EL","name":"Öl","hinweis":""}]},{"gruppe":"Beilagen","liste":[{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"hart gekocht"},{"menge":4,"einheit":"EL","name":"Shito (scharfe Pfeffersauce)","hinweis":"Afroshop; enthält meist getrocknete Garnelen oder Fisch – für rein vegetarisch scharfes Chiliöl nehmen"},{"menge":2,"einheit":"EL","name":"Gari (Maniokgrieß)","hinweis":"optional, zum Darüberstreuen"},{"menge":2,"einheit":"Stück","name":"reife Kochbananen","hinweis":"in Scheiben, Öl zum Braten"}]},{"gruppe":"Kohlsalat","liste":[{"menge":250,"einheit":"g","name":"Weißkohl","hinweis":"sehr fein gehobelt"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"gewürfelt"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in dünnen Ringen"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"Saft"},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""}]}],"ausruestung":["großer Topf mit Deckel","Sieb","Pfanne für die Kochbananen","Messer und Brett"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Reis und Bohnen ab. Spüle die Sorghum-Blattscheiden kurz unter kaltem Wasser ab; sie färben stark und verlieren sonst im Topf ihren Farbstoff schon vor dem Kochen. Schneide die Zwiebel in Viertel, hobele den Weißkohl für den Salat fein und würfele die Tomaten. Koche die Eier in 9–10 Minuten hart, schrecke sie ab und stelle sie bereit. Wenn du keine Blattscheiden bekommst, lege 1 TL Natron zum Kochen bereit.","dauer":15,"tipp":""},{"titel":"Bohnen einweichen","aktion":"einlegen","text":"Bedecke die getrockneten Bohnen mit der dreifachen Menge kaltem Wasser und lasse sie über Nacht, mindestens 8 Stunden, quellen. Dadurch kochen sie gleichmäßig und leichter verdaulich. Gieße das Einweichwasser ab und spüle die Bohnen ab. Sie sollten nun etwa doppelt so groß sein, sich beim Drücken zwischen den Fingern leicht eindrücken lassen und nicht mehr hart sein.","dauer":0,"tipp":""},{"titel":"Bohnen mit Blättern kochen","aktion":"kochen","text":"Gib die Bohnen mit Zwiebel, Chili, den Sorghum-Blättern (oder Natron) und 1,2 Litern frischem Wasser in den Topf. Bringe es zum Kochen, schöpfe den grauen Schaum ab und lasse die Bohnen bei kleiner Hitze 45–60 Minuten sanft köcheln, bis sie weich, aber noch formstabil sind. Das Wasser färbt sich langsam tiefrot bis dunkelbraun – das ist das Zeichen, dass die Blätter ihre Wirkung entfalten. Probiere eine Bohne: Sie soll cremig zerdrücken, aber nicht zerfallen.","dauer":55,"tipp":"Salz erst gegen Ende zugeben; früh gesalzenes Wasser kann die Bohnenschale zäh machen."},{"titel":"Reis waschen","aktion":"vorbereiten","text":"Gib den Reis in eine Schüssel, bedecke ihn mit kaltem Wasser und reibe ihn sanft zwischen den Händen, bis das Wasser milchig wird. Gieße ab und wiederhole das drei- bis viermal, bis das Wasser fast klar ist. So verschwindet überschüssige Stärke, und der Reis wird später locker und nicht klebrig. Lass ihn anschließend im Sieb gut abtropfen.","dauer":8,"tipp":""},{"titel":"Flüssigkeit einstellen, Reis zugeben","aktion":"kochen","text":"Nimm die Blattscheiden mit einem Löffel heraus; sie haben ihre Farbe abgegeben und werden nicht mitgegessen. Miss die Flüssigkeit im Topf: Für 400 g Parboiled-Reis brauchst du etwa 700–750 ml; gieße überschüssiges Wasser ab oder fülle mit kochendem Wasser auf. Rühre Salz und Öl ein, gib den Reis hinzu und glätte die Oberfläche. Bringe alles zum Köcheln, decke den Topf fest ab und senke die Hitze auf die niedrigste Stufe.","dauer":5,"tipp":""},{"titel":"Reis garen und quellen lassen","aktion":"daempfen","text":"Lass den Reis bei niedrigster Hitze 15 Minuten zugedeckt garen, ohne den Deckel zu heben. Schalte dann die Hitze aus und lasse den Topf weitere 15 Minuten geschlossen stehen. Die Flüssigkeit ist dann vollständig aufgesogen, die Reiskörner sind weich, aber getrennt, und das Ganze duftet nach Bohnen, Zwiebel und einem rauchigen, leicht erdigen Ton. Hebe zum Schluss alles mit einer Gabel locker auf.","dauer":30,"tipp":"Der Reis darf rotbraun und marmoriert aussehen – er ist fertig, wenn er körnig ist, nicht matschig."},{"titel":"Kohlsalat und Kochbananen","aktion":"schneiden","text":"Mische Kohl, Tomaten und Zwiebel mit Limettensaft, Öl und einer Prise Salz und lasse den Salat 10 Minuten ziehen. Brate Kochbananenscheiben in 1 cm Öl bei mittlerer Hitze 2–3 Minuten pro Seite, bis sie goldbraun und am Rand karamellisiert sind. Lege sie auf Küchenpapier. Der knackige Salat und die süße Banane gleichen die Schärfe des Shito aus.","dauer":15,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Häufe den Waakye auf Teller oder – wie in Ghana – auf Bananenblätter. Lege je ein halbes Ei, einen Löffel Salat, Kochbananen und einen Klecks Shito daneben. Streue etwas Gari über den Reis, damit er die Feuchtigkeit der Beilagen aufnimmt. Das Gericht soll bunt, warm und duftend serviert werden; jeder mischt sich seine Bissen selbst.","dauer":5,"tipp":""}],"profitipps":["Verwende Parboiled-Reis; Basmati und Rundkornreis neigen dazu, in der Bohnenbrühe zu verkleben.","Die Blattscheiden färben wie Tee – nicht zu lange einweichen, aber ruhig mitkochen und vor dem Servieren entfernen.","Natron-Ersatz: 1 TL für 250 g Bohnen – mehr macht den Reis seifig.","Shito (Pfeffersauce mit getrocknetem Fisch/Krabben und Chili) macht aus dem milden Reis ein vollständiges Gericht; ersatzweise eignet sich jedes scharfe Chiliöl.","Waakye wird in Ghana als Frühstück oder Mittagessen gegessen und mit Beilagen nach Belieben kombiniert."],"varianten":["Zoe Adjonyohs Version mit Naturreis, Zwiebel und frischer Chili, garniert mit weichem Ei, Schnittlauch und grüner Chili.","Mit gebratenem Fisch oder Rindfleisch-Stew (Wele) als Beilage.","Mit Spaghetti (in Ghana „Talia“) als Beilage, wie es Straßenhändler anbieten.","Vegane Variante ohne Ei mit mehr Salat und Kochbananen."],"beilagen":["Shito","gekochte Eier","Kohlsalat","frittierte Kochbananen","Gari"],"getraenk":"Gekühltes Hibiskusgetränk (Sobolo), Ingwerlimonade oder Wasser mit Limette","koeche":[{"name":"Zoe Adjonyoh","bezug":"In ihrem Buch „Zoe’s Ghana Kitchen“ stellt die britisch-ghanaische Köchin einen Waakye-Reis vor, bei dem sie mehr Stärke auswäscht, Zwiebel und frische Chili ergänzt und Natron als Ersatz für Sorghum-Blätter nennt.","quelle":"https://www.nigella.com/recipes/guests/zoe-adjonyohs-waakye-rice"}],"quellen":[{"titel":"Wikipedia – Waakye","url":"https://en.wikipedia.org/wiki/Waakye"},{"titel":"Nigella.com – Zoe Adjonyoh's Waakye Rice","url":"https://www.nigella.com/recipes/guests/zoe-adjonyohs-waakye-rice"}],"bild":"reis","farben":["#7b2d1d","#b5532f","#f0d9b5"],"schlagworte":["Frühstück in Ghana","Reis und Bohnen","Straßenessen","Hülsenfrüchte"],"themen":["streetfood"],"vegetarisch_moeglich":true},{"id":"westafrika-pepper-soup-ziege","name":"Pepper Soup mit Ziege","originalname":"Goat Pepper Soup","kueche":"westafrika","region":"Nigeria","beliebtheit":75,"hauptkategorie":"fleisch","fleischsorte":"ziege","fischsorte":"","gang":"suppe","kurz":"Scharfe, aromatische Brühe mit zartem Ziegenfleisch, Ingwer, Gewürznüssen und Duftblättern – wärmend, klar und herrlich anregend.","hintergrund":"Pepper Soup ist eine dünne, scharf-würzige Suppe, die in Nigeria, Kamerun und anderen Teilen Westafrikas gekocht wird. Sie gilt als Wohlfühlessen, wird in Bars zum kalten Bier gereicht, nach Hochzeiten serviert und Wöchnerinnen zur Stärkung gegeben. Das Aroma kommt von Chili, Ingwer und einer Gewürzmischung mit Calabash-Muskat (Ehuru) sowie frischen Duftblättern; die Suppe ist weniger glühend scharf als aromatisch-nussig und würzig. Man nimmt Ziege, Huhn, Rind, Innereien oder Fisch.","portionen":4,"zeit":{"vorbereitung":25,"garen":100,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Brühe","liste":[{"menge":1,"einheit":"kg","name":"Ziegenfleisch mit Knochen","hinweis":"Schulter oder Keule, in 4–5 cm Stücke; beim türkischen oder halal-Metzger; Ersatz: Lammschulter"},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"grob gewürfelt"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ingwerstück (ca. 5 cm)","hinweis":"frisch"},{"menge":1.5,"einheit":"l","name":"Wasser","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"Brühwürfel","hinweis":"optional, mit Fleischgeschmack"}]},{"gruppe":"Pepper-Soup-Gewürz","liste":[{"menge":2,"einheit":"EL","name":"Pepper-Soup-Gewürzmischung","hinweis":"Afroshop – meist mit Calabash-Muskat (Ehuru), Uziza, Uda"},{"menge":0.5,"einheit":"TL","name":"Muskatnuss","hinweis":"Ersatz, falls keine Mischung: frisch gerieben"},{"menge":1,"einheit":"TL","name":"Koriandersamen","hinweis":"Ersatz-Teil, trocken geröstet"},{"menge":0.5,"einheit":"TL","name":"Nelken","hinweis":"Ersatz-Teil"},{"menge":1,"einheit":"TL","name":"schwarze Pfefferkörner","hinweis":"Ersatz für Uziza"},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet oder Habanero","hinweis":"nach Schärfe 1–2"}]},{"gruppe":"Zum Finish","liste":[{"menge":1,"einheit":"Handvoll","name":"frisches Basilikum oder Thai-Basilikum","hinweis":"Ersatz für Scent Leaf (Nchanwu/Efirin)"},{"menge":1,"einheit":"Stück","name":"reife Tomate","hinweis":"klein gewürfelt, optional"},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":"zum Servieren"}]}],"ausruestung":["großer Topf mit Deckel","Mörser oder Gewürzmühle","Schaumlöffel","Messer und Brett"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Ziegenfleisch in Stücke von 4–5 cm, mit Knochen, denn sie geben der Brühe ihre Tiefe. Wasche das Fleisch kurz ab und tupfe es trocken. Würfele Zwiebeln grob, hacke den Knoblauch und reibe den Ingwer. Ritze die Chili einmal ein und lass sie ganz; so gibt sie Aroma ab, ohne die Suppe unkontrollierbar scharf zu machen. Das Basilikum waschen, trocken schleudern und beiseitelegen.","dauer":15,"tipp":""},{"titel":"Fleisch blanchieren","aktion":"blanchieren","text":"Gib das Fleisch in einen Topf, bedecke es mit kaltem Wasser und bringe es langsam zum Kochen. Es bildet sich grau-bräunlicher Schaum, den du mit dem Schaumlöffel abschöpfst. Koche 5 Minuten und gieße das Wasser samt Resten ab; spüle das Fleisch kurz ab. Die Ziege riecht dabei intensiv, und genau diese Nebengerüche verschwinden, sodass die Brühe später klar und sauber schmeckt.","dauer":10,"tipp":"Dieser Schritt unterscheidet eine saubere Pepper Soup von einer trüben, strengen."},{"titel":"Fleisch ansetzen","aktion":"kochen","text":"Gib das Fleisch zurück in den Topf und füge Zwiebel, Knoblauch, Ingwer, 1,5 Liter Wasser, Salz und optional den Brühwürfel hinzu. Bringe alles zum Köcheln und lasse es zugedeckt bei mittlerer bis schwacher Hitze 45 Minuten garen. Die Oberfläche soll nur leise blubbern; zu starkes Kochen macht die Brühe trüb und das Fleisch faserig. Die Brühe duftet jetzt nach Zwiebel, Ingwer und Fleisch.","dauer":45,"tipp":""},{"titel":"Gewürz rösten und mahlen","aktion":"mischen","text":"Röste in einer trockenen Pfanne bei mittlerer Hitze Koriander, Pfeffer und Nelken 1–2 Minuten, bis sie duften. Gib sie mit Muskat in den Mörser und zerstoße alles fein, oder nimm einfach 2 EL der fertigen Pepper-Soup-Mischung. Das Rösten weckt die ätherischen Öle; werden die Gewürze dunkel, riechen sie bitter und du fängst neu an. Das Pulver soll warm, nussig und leicht holzig riechen – so schmeckt Pepper Soup.","dauer":5,"tipp":""},{"titel":"Würzen und weiter köcheln","aktion":"koecheln","text":"Rühre das Gewürzpulver in die Brühe und gib die ganze oder halbierte Scotch Bonnet dazu. Köchele die Suppe zugedeckt weitere 30–40 Minuten, bis das Fleisch sich leicht vom Knochen löst und zart ist. Die Brühe sollte kräftig golden-braun, klar und glänzend sein, an der Oberfläche ein paar Fettaugen. Zerplatzt die Chili, wird die Suppe schnell sehr scharf; nimm sie dann sofort heraus.","dauer":40,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Brühe: Sie soll scharf-würzig, leicht nussig, warm und gut gesalzen schmecken. Fehlt Tiefe, kommt eine Prise Salz oder ein halber Brühwürfel dazu; ist sie zu scharf, verdünnst du mit heißem Wasser oder lässt die Chili heraus. Gib die Tomate hinein und gare 5 Minuten; sie bringt Frische und eine leichte Säure. Nimm die Chili jetzt heraus, wenn dir die Schärfe reicht.","dauer":5,"tipp":""},{"titel":"Duftblätter einrühren","aktion":"garnieren","text":"Zupfe das Basilikum in Stücke und rühre es unmittelbar vor dem Servieren in die kochend heiße Suppe. Bei einigen Sekunden Hitze verströmt es seinen Duft, bleibt aber grün und frisch. Länger gekocht wird es dunkel und bitter. Die Suppe soll nun nach Ingwer, Nelke, Muskat und frischen Kräutern duften – ein grüner Akzent über der warmen Brühe.","dauer":2,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Schöpfe Fleisch und Brühe in tiefe Schalen, jede mit mehreren Fleischstücken und Knochen. Serviere die Suppe sehr heiß mit Limettenspalten. In Nigeria isst man sie zum Löffeln und zum Abnagen der Knochen, oft mit gekochter Yamswurzel, Reis oder Kochbananen; dazu passt ein kaltes Bier. Wer mag, drückt Limette hinein – das hebt das Aroma.","dauer":3,"tipp":""}],"profitipps":["Das Blanchieren des Fleisches macht die Brühe klar und nimmt dem Fleisch Fremdgeruch.","Echte Pepper-Soup-Gewürzmischung aus dem Afroshop enthält Zutaten, die schwer zu ersetzen sind; die Ersatzmischung aus Muskat, Koriander, Nelke und Pfeffer kommt aber überraschend nah.","Pepper Soup wird nicht gebunden und soll dünn bleiben; Fufu kann zum Eintauchen dazu gereicht werden.","Wer Fisch statt Ziege nimmt, kocht nur 15–20 Minuten: erst Gewürzbrühe, dann Fisch hineinlegen.","Nach einem Tag im Kühlschrank schmeckt die Suppe oft noch besser."],"varianten":["Catfish Pepper Soup mit Wels oder anderem Süßwasserfisch – eine beliebte Fischversion; der Fisch gart nur wenige Minuten in der fertigen Brühe.","Chicken Pepper Soup mit Hähnchenkeulen.","Mit gemischten Fleischsorten und Innereien (Assorted Meat Pepper Soup).","Mit Fufu eingedickt zu einer cremigeren Suppe."],"beilagen":["gekochte Yamswurzel","Reis","gebratene Kochbananen","Fufu"],"getraenk":"Kaltes Lagerbier – so wird Pepper Soup in Nigerias Bars genossen","koeche":[],"quellen":[{"titel":"Wikipedia – Pepper soup","url":"https://en.wikipedia.org/wiki/Pepper_soup"},{"titel":"Wikipedia – Nigerian cuisine","url":"https://en.wikipedia.org/wiki/Nigerian_cuisine"}],"bild":"suppe","farben":["#7a3b12","#c8651b","#f2d8a7"],"schlagworte":["Wohlfühlsuppe","scharf","Nigeria","Biersnack"],"vegetarisch_moeglich":false},{"id":"westafrika-akara","name":"Akara – Schwarzaugenbohnen-Krapfen","originalname":"Akara (Accara, Kosai, Koose)","kueche":"westafrika","region":"Nigeria, Benin, Senegal, Ghana","beliebtheit":74,"hauptkategorie":"vegan","fleischsorte":"","fischsorte":"","gang":"snack","kurz":"Luftig aufgeschlagener Bohnenteig, im heißen Öl knusprig frittiert: außen eine feine Kruste, innen weich, würzig und leicht scharf.","hintergrund":"Akara stammt von den Yoruba im Südwesten Nigerias und ist in ganz Westafrika verbreitet: In Senegal heißt es Accara, bei den Hausa Kosai, in Ghana Koose. Der Teig aus geschälten Schwarzaugenbohnen wird lange geschlagen, damit er luftig wird. Man isst Akara zum Frühstück mit Brot oder Maispudding (Ogi), als Straßensnack und bei Festen. Mit den Menschen, die aus Westafrika verschleppt wurden, kam das Gericht nach Bahia in Brasilien, wo daraus Acarajé wurde. Pierre Thiam beschreibt Accara als die senegalesische Antwort auf Hush Puppies.","portionen":4,"zeit":{"vorbereitung":40,"garen":20,"ruhen":300},"schwierigkeit":2,"zutaten":[{"gruppe":"Teig","liste":[{"menge":300,"einheit":"g","name":"getrocknete Schwarzaugenbohnen","hinweis":"Supermarkt, Bioladen oder Afroshop"},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel (ca. 80 g)","hinweis":"grob geschnitten"},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet oder rote Chilischote","hinweis":"nach Schärfe, entkernen für milder"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":80,"einheit":"ml","name":"kaltes Wasser","hinweis":"esslöffelweise, nach Bedarf"}]},{"gruppe":"Zum Frittieren","liste":[{"menge":1,"einheit":"l","name":"Pflanzenöl","hinweis":"Erdnuss- oder Rapsöl; Palmöl gibt eine kräftigere Note"}]},{"gruppe":"Tomaten-Chili-Sauce","liste":[{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Zwiebel","hinweis":""},{"menge":1,"einheit":"Stück","name":"Chilischote","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""}]}],"ausruestung":["Mixer oder Stabmixer","große Schüssel","Schneebesen oder Handrührgerät","hoher Topf oder Fritteuse","Küchenthermometer","Schaumlöffel","Esslöffel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Verlese die Bohnen und entferne Steinchen oder angeschlagene Körner. Stelle Zwiebel, Chili und Salz bereit und schneide die Zwiebel grob. Bereite das Frittieröl und die Zutaten für die Sauce vor, bevor der Teig fertig ist, denn der aufgeschlagene Teig muss zügig ins Öl. Lege ein Sieb in die Spüle und eine große Schüssel mit Wasser bereit, die du für das Enthäuten brauchst.","dauer":10,"tipp":""},{"titel":"Bohnen einweichen","aktion":"einlegen","text":"Bedecke die Bohnen mit dem dreifachen Volumen kaltem Wasser und lasse sie 4–6 Stunden quellen, bis sie fast doppelt so groß und innen nicht mehr hart sind. Zu lange Einweichzeit macht den Teig wässrig und die Akara dicht, zu kurze lässt ihn körnig bleiben. Gieße das Wasser ab, bevor du weiterarbeitest. Die Bohnen riechen jetzt neutral-nussig und die Schale beginnt sich zu lösen.","dauer":0,"tipp":""},{"titel":"Häutchen entfernen","aktion":"vorbereiten","text":"Fülle die Bohnen in eine große Schüssel mit frischem Wasser und reibe sie kräftig zwischen den Handflächen oder rühre sie mit dem Löffel um. Die dünnen Häutchen lösen sich und schwimmen oben, sodass du sie mit einem Sieb abschöpfen kannst. Wechsle das Wasser 3–4 Mal, bis fast alle Schalen weg sind. Ein paar Reste sind in Ordnung, aber ohne die Schalen wird Akara heller, zarter und luftiger. Lass die Bohnen im Sieb gut abtropfen.","dauer":15,"tipp":"Wer es eilig hat, pulst die eingeweichten Bohnen kurz im Mixer mit Wasser an – die Schalen steigen dann auf und lassen sich abgießen."},{"titel":"Zu feinem Teig mixen","aktion":"puerieren","text":"Püriere die Bohnen mit Zwiebel, Chili und 3–4 EL Wasser portionsweise im Mixer zu einer sehr feinen, cremigen Masse. Gib das Wasser nur löffelweise zu: Der Teig soll dick wie Hummus bleiben, damit er später im Öl Form hält. Wenn er zu flüssig wird, geht er im Öl auseinander. Streiche ihn zwischendurch vom Rand ab; er soll glatt sein und leicht nach rohen Bohnen riechen.","dauer":8,"tipp":""},{"titel":"Luftig aufschlagen","aktion":"aufschlagen","text":"Schlage den Teig in einer großen Schüssel 5–8 Minuten mit dem Schneebesen oder dem Handrührgerät auf höchster Stufe, bis er deutlich heller, voluminös und fluffig wird. Rühre zum Schluss das Salz unter. Mache die Schwimmprobe: Ein Löffel Teig, in kaltes Wasser getropft, soll an der Oberfläche schwimmen. Sinkt er, schlage weiter. Je mehr Luft im Teig, desto leichter wird Akara.","dauer":8,"tipp":"Salz erst zum Schluss einrühren; früh zugegeben macht es den Teig wässrig."},{"titel":"Sauce kochen","aktion":"kochen","text":"Püriere Tomaten, Zwiebel, Chili und Knoblauch fein und gieße das Püree in einen Topf mit heißem Öl. Köchele es bei mittlerer Hitze 10–12 Minuten ein, bis die Sauce dickflüssig ist und das Öl an den Rändern sichtbar wird. Würze mit Salz. Sie soll fruchtig, scharf und etwas süß schmecken. Stelle sie zum Dippen bereit, warm oder bei Zimmertemperatur.","dauer":12,"tipp":""},{"titel":"Öl erhitzen","aktion":"frittieren","text":"Erhitze das Öl in einem hohen Topf auf 180 °C. Prüfe die Temperatur mit dem Thermometer oder lasse einen Teelöffel Teig ins Öl fallen: Er soll sofort sprudeln, aufsteigen und goldfarben werden. Zu kaltes Öl macht die Akara schwer, zu heißes bräunt sie außen, bevor sie innen gar sind. Fülle den Topf nur zu einem Drittel, denn der Teig schäumt auf.","dauer":8,"tipp":""},{"titel":"Löffelweise frittieren","aktion":"frittieren","text":"Tauche zwei Esslöffel kurz ins Öl, nimm mit einem eine Portion Teig auf und lasse sie mit dem zweiten Löffel ins heiße Öl gleiten. Arbeite in Chargen von 5–6 Stück und halte den Teig zwischendurch kühl. Die Krapfen steigen auf, drehen sich selbst oder werden nach 2 Minuten gewendet. Frittiere sie weitere 2–3 Minuten, bis sie rundum tief goldbraun und knusprig sind und nach gerösteten Bohnen und Zwiebeln duften.","dauer":15,"tipp":""},{"titel":"Abtropfen und servieren","aktion":"anrichten","text":"Hebe die Akara mit dem Schaumlöffel heraus und lasse sie auf Küchenpapier abtropfen. Serviere sie sofort heiß mit der Tomatensauce: Die Kruste knistert, innen sind die Krapfen weich und luftig. Wärme übriggebliebene Akara später im Ofen bei 180 °C 5 Minuten auf. Sie schmecken pur, im Brötchen oder mit Maisbrei.","dauer":3,"tipp":""}],"profitipps":["Der Schlüssel ist das lange Aufschlagen: Je mehr Luft im Teig, desto lockerer und leichter wird Akara.","Teig nicht lange stehen lassen – er verliert Luft; lieber sofort ausbacken.","Wassermenge sparsam – ein zu flüssiger Teig zerfällt im Öl.","Die Schwimmprobe im Wasserglas verrät, ob der Teig luftig genug ist.","Das Öl immer wieder auf 180 °C bringen lassen; nach jeder Charge kurz warten."],"varianten":["Accara im Senegal: meist als Bällchen mit scharfer Tomaten-Chili-Sauce serviert; die Food-Network-Version wälzt sie in Maismehl.","Akara Osu: heller und puffiger, mit Zwiebel, Paprika und Garnelen.","Akara Awon mit Okra im Teig.","Acarajé aus Bahia: größere Form, in Dendê-Öl gebraten und mit Garnelenpaste gefüllt."],"beilagen":["Ogi (Maisbrei)","frisches Weißbrot","Tomaten-Chili-Sauce","Shito"],"getraenk":"Heißer Ogi-Brei, Tee oder frisch gepresster Orangensaft","koeche":[{"name":"Pierre Thiam","bezug":"Der senegalesische Koch beschreibt Accara – pürierte, getrocknete Schwarzaugenbohnen, zu Krapfen frittiert – als die senegalesische Version der Hush Puppies.","quelle":"https://www.saveur.com/article/Kitchen/Senegal-Pierre-Thiam"}],"quellen":[{"titel":"Wikipedia – Akara","url":"https://en.wikipedia.org/wiki/Akara"},{"titel":"Saveur – The Flavors of Senegal (Pierre Thiam)","url":"https://www.saveur.com/article/Kitchen/Senegal-Pierre-Thiam"},{"titel":"Food Network – Black-Eyed Pea Fritters (Accara)","url":"https://www.foodnetwork.com/recipes/black-eyed-pea-fritters-accara-2109668"}],"bild":"gebaeck","farben":["#a8621f","#d9a04a","#f7e2b8"],"schlagworte":["Straßenessen","vegan","Frühstück","Bohnen"],"themen":["streetfood"],"vegetarisch_moeglich":true},{"id":"westafrika-banku-tilapia","name":"Banku mit gegrillter Tilapia und Pepper Sauce","originalname":"Banku and Tilapia","kueche":"westafrika","region":"Ghana (Accra, Volta-Region)","beliebtheit":74,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Säuerlicher Kloß aus fermentiertem Mais- und Maniokteig, dazu ein knusprig gegrillter Tilapia mit frischer, feuriger Pfeffersauce.","hintergrund":"Banku und Tilapia sind in Ghana ein Pärchen: In Accra gibt es ganze „Banku-and-Tilapia-Joints“, wo der Fisch auf dem Holzkohlegrill liegt und der Kloß frisch gerührt wird. Banku besteht aus fermentiertem Mais- und Maniokteig, der zu einem glatten, leicht klebrigen Kloß gerührt wird; man isst ihn mit der Hand, indem man kleine Stücke abzupft und in Pfeffersauce taucht. Der Fisch wird mit Zwiebel, Ingwer, Knoblauch und Chili mariniert. Die säuerliche Note vom Gären macht Banku zur idealen Ergänzung zu scharfem Fisch.","portionen":4,"zeit":{"vorbereitung":40,"garen":60,"ruhen":2880},"schwierigkeit":3,"zutaten":[{"gruppe":"Banku-Teig","liste":[{"menge":250,"einheit":"g","name":"feines Maismehl","hinweis":"nicht Polenta-Grieß; Afroshop (Corn flour/Maize meal) oder feines Maismehl aus dem Reformhaus"},{"menge":200,"einheit":"g","name":"Maniokmehl (Cassava flour)","hinweis":"Afroshop; Ersatz: Tapiokastärke, dann etwas weniger klebrig"},{"menge":2,"einheit":"EL","name":"Naturjoghurt","hinweis":"hilft der Fermentation als Starter"},{"menge":500,"einheit":"ml","name":"lauwarmes Wasser","hinweis":"für den Ansatz"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":500,"einheit":"ml","name":"Wasser","hinweis":"zum Kochen des Kloßes"}]},{"gruppe":"Fisch","liste":[{"menge":2,"einheit":"Stück","name":"Tilapia, küchenfertig (je 600–700 g)","hinweis":"Afro-/Asiashop, TK; Ersatz: Dorade, Wolfsbarsch oder Forelle"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ingwerstück (ca. 4 cm)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet","hinweis":"nach Schärfe"},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":3,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"EL","name":"Limettensaft","hinweis":""}]},{"gruppe":"Pepper Sauce","liste":[{"menge":4,"einheit":"Stück","name":"reife Tomaten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":2,"einheit":"Stück","name":"Habanero oder Scotch Bonnet","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"Fischsauce","hinweis":"optional, ersetzt getrockneten Fisch"}]},{"gruppe":"Zum Servieren","liste":[{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"in Scheiben"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in Ringen"}]}],"ausruestung":["Kohlegrill oder Backofen-Grill","großer Topf (Edelstahl, gerade Wand)","kräftiger Holzlöffel","Mörser oder Mixer","kleine Schüsseln zum Formen","Frischhaltefolie"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Plane zwei Tage ein, denn Banku lebt von der Fermentation. Wiege Mais- und Maniokmehl ab, stelle Joghurt und lauwarmes Wasser bereit und reinige den Fisch: Tilapia unter kaltem Wasser abspülen, Schuppen kontrollieren und die Bauchhöhle auswischen. Schneide Zwiebel, Ingwer und Knoblauch grob für die Marinade. Die Scotch Bonnet bleibt ganz, bis du sie brauchst – Chili an den Fingern sollte nicht ins Auge gelangen.","dauer":15,"tipp":""},{"titel":"Banku-Teig ansetzen","aktion":"mischen","text":"Vermische Mais- und Maniokmehl mit den 500 ml lauwarmem Wasser und dem Joghurt zu einem glatten, dickflüssigen Teig ohne Klümpchen. Fülle ihn in eine Schüssel, decke sie locker mit einem Tuch ab und lasse den Teig 2 Tage bei 25–30 °C stehen, etwa neben der Heizung oder im Backofen mit eingeschalteter Lampe. Er beginnt zu blubbern, riecht angenehm säuerlich-joghurtig und schmeckt zart sauer. Wenn er riecht wie Essig oder gärt ungewöhnlich, war es zu warm.","dauer":0,"tipp":"Je länger der Teig gärt (bis 3 Tage), desto säuerlicher wird Banku. Für den Anfang reichen 36–48 Stunden."},{"titel":"Fisch marinieren","aktion":"marinieren","text":"Zerstoße Zwiebel, Knoblauch, Ingwer, Chili, Salz und Limettensaft im Mörser oder Mixer zu einer groben, würzigen Paste und rühre das Öl ein. Ritze die Tilapia auf beiden Seiten 3–4 Mal schräg bis auf die Gräten ein, damit Hitze und Marinade eindringen. Reibe den Fisch außen und in der Bauchhöhle kräftig ein und lasse ihn abgedeckt 1 Stunde im Kühlschrank ziehen. Die Haut soll nass-würzig sein, nicht mit dicken Brocken bedeckt, sonst verbrennen sie.","dauer":60,"tipp":""},{"titel":"Pepper Sauce herstellen","aktion":"mischen","text":"Zerkleinere Tomaten, Zwiebel, Habanero und Salz im Mörser oder Mixer grob. Die Sauce soll nicht fein püriert sein, sondern leicht stückig, mit frischem Tomatengeruch und scharfem Biss. Schmecke sie ab: Sie soll sehr scharf, frisch und säuerlich-fruchtig sein; wenn nötig, ergänzst du Salz. Die rohe Pepper Sauce ist der klassische Begleiter, Fischsauce gibt Tiefe. Stelle sie kalt.","dauer":10,"tipp":""},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Heize den Kohlegrill mit Holzkohle vor, bis sie weiß belegt ist, und sorge für eine direkte und eine indirekte Zone (180–200 °C). Reibe den Rost mit etwas Öl ein, damit die Haut nicht klebt. Alternativ nutzt du die Grillfunktion im Backofen auf 250 °C, Rost auf der obersten Schiene mit Backblech darunter. Ein heißer, sauberer Rost ist entscheidend für eine knusprige Haut.","dauer":15,"tipp":""},{"titel":"Tilapia grillen","aktion":"grillen","text":"Lege die Fische auf den Rost über die mittlere Hitze und grille sie ca. 10–12 Minuten pro Seite, bis die Haut tief gebräunt, blasig und stellenweise knusprig ist. Wende sie nur einmal mit einem breiten Pfannenwender. Das Fleisch ist gar, wenn es an der dicksten Stelle bei etwa 62–65 °C milchigweiß und saftig ist und sich von den Gräten löst. Fisch, der klebt, ist noch nicht bereit zum Wenden – warte, bis er sich leicht löst.","dauer":25,"tipp":"Reibe die Haut zwischendurch mit etwas Marinade ein, sie bleibt feucht und aromatisch."},{"titel":"Banku-Teig kochen","aktion":"kochen","text":"Rühre den fermentierten Teig durch und gib ihn mit Salz und 500 ml kaltem Wasser in den Topf. Erhitze alles bei mittlerer Hitze und rühre dabei ununterbrochen mit dem Holzlöffel, bis der Teig nach 4–5 Minuten andickt und klumpig wird. Ab jetzt arbeitest du kräftig: Presse den Teig gegen die Topfwand und rühre ihn glatt. Er wird immer zäher, glänzender und klebriger und ähnelt am Ende einem schweren Kloßteig.","dauer":15,"tipp":""},{"titel":"Banku dämpfen und glatt rühren","aktion":"daempfen","text":"Senke die Hitze, decke den Topf ab und lasse den Teig 5 Minuten dämpfen. Rühre danach erneut kräftig 2–3 Minuten und wiederhole das Dämpfen noch einmal; insgesamt dauert es etwa 20–25 Minuten. Banku ist fertig, wenn er glatt, elastisch und klebrig ist, sich vom Topf löst und keinen mehligen Geschmack mehr hat. Ist er noch körnig, brauchst du mehr Rühren; ist er zu fest, gib einen Schuss heißes Wasser dazu.","dauer":25,"tipp":""},{"titel":"Banku formen","aktion":"formen","text":"Befeuchte eine kleine Schüssel oder lege sie mit Frischhaltefolie aus. Fülle eine Kelle Banku hinein, schwenke die Schüssel, bis ein glatter, runder Kloß entsteht, und stürze ihn auf einen Teller. Die Oberfläche soll glänzen und glatt sein. Halte die Kugeln unter einem feuchten Tuch warm; Banku wird beim Abkühlen fest und klebrig.","dauer":5,"tipp":""},{"titel":"Anrichten und essen","aktion":"anrichten","text":"Lege je einen Kloß und einen Fisch auf einen Teller und gib einen Löffel Pepper Sauce daneben; dazu Tomatenscheiben und Zwiebelringe. Gegessen wird mit der rechten Hand: Pflücke ein kleines Stück Banku ab, tauche es in die Sauce und kombiniere es mit einem Stück Fisch. Der Kloß schmeckt leicht sauer, die Sauce scharf und frisch, der Fisch rauchig und saftig.","dauer":5,"tipp":""}],"profitipps":["Ohne Fermentation schmeckt Banku fad – nimm dir die zwei Tage Zeit.","Der Kloß braucht Kraft: Die Teigmasse wird erst durch intensives Rühren elastisch und glatt.","Banku schmeckt frisch am besten; bis zum Servieren hältst du die Kugeln unter einem feuchten Tuch warm.","Der Fisch gart am besten ganz und auf der Gräte, so bleibt das Fleisch saftig.","Wer keinen Grill hat: Fisch im 250 °C heißen Ofen (Grillfunktion) 10–12 Minuten pro Seite garen."],"varianten":["Banku mit Okra-Eintopf (Okro Stew) statt Fisch.","Mit gebratenem Fisch (Fried Tilapia) statt gegrillt.","Mit Kenkey, dem gedämpften, noch säuerlicheren Maisklos, als verwandte Beilage.","Mit Krabben und scharfer Tomatensauce."],"beilagen":["Pepper Sauce","Tomaten-Zwiebel-Salat","Shito","Okra-Eintopf"],"getraenk":"Eisgekühltes Lagerbier oder Malzbier (Malta Guinness); in Ghana auch Sobolo","koeche":[],"quellen":[{"titel":"Culture Trip – A Hearty Guide to Ghana’s Banku","url":"https://theculturetrip.com/africa/ghana/articles/a-hearty-guide-to-ghanas-banku"},{"titel":"Graphic Online – Business booms at banku and tilapia joints","url":"https://www.graphic.com.gh/news/general-news/business-booms-at-banku-and-tilapia-joints.html"}],"bild":"fisch","farben":["#8c5a2b","#d6a85a","#f2e5c9"],"schlagworte":["Ghana","Fisch vom Grill","fermentiert","scharf"],"themen":["grill","streetfood"],"vegetarisch_moeglich":false},{"id":"westafrika-mafe","name":"Mafé – Erdnusseintopf mit Rindfleisch","originalname":"Mafé / Maafe / Tigadègè","kueche":"westafrika","region":"Senegal","beliebtheit":72,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Zarte Rindfleischstücke und Gemüse in sämiger Erdnuss-Tomaten-Sauce, serviert über Reis.","hintergrund":"Mafé ist ein Eintopf mit Erdnusssauce, der in Mali, Senegal, Gambia und weiteren Ländern Westafrikas gegessen wird. Traditionell kocht man Rind-, Lamm- oder Hühnerfleisch mit Zwiebeln, Tomaten und Gemüse und bindet die Sauce mit Erdnusspaste. Die Sauce soll cremig, dick und rötlich-braun sein und durch Öl glänzen, das sich oben absetzt. Dazu isst man Reis. Pierre Thiam, Küchenchef und Kochbuchautor aus Senegal, beschreibt, wie in der senegalesischen Küche Aromen Schicht um Schicht aufgebaut werden.","portionen":6,"zeit":{"vorbereitung":30,"garen":100,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Basis","liste":[{"menge":900,"einheit":"g","name":"Rindfleisch (Schulter oder Wade)","hinweis":"in 3–4 cm Würfel"},{"menge":3,"einheit":"EL","name":"Erdnussöl","hinweis":""},{"menge":2,"einheit":"Stück","name":"große Zwiebeln","hinweis":"fein gehackt"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Ingwer, daumengroß","hinweis":"gerieben"},{"menge":3,"einheit":"EL","name":"Tomatenmark","hinweis":""},{"menge":400,"einheit":"g","name":"stückige Tomaten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet","hinweis":"ganz, nicht aufstechen"},{"menge":1,"einheit":"TL","name":"getrockneter Thymian","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"l","name":"Wasser oder Rinderbrühe","hinweis":""},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Sauce und Gemüse","liste":[{"menge":200,"einheit":"g","name":"ungesüßte Erdnussbutter","hinweis":"100 % Erdnuss, ohne Zucker"},{"menge":3,"einheit":"Stück","name":"Karotten","hinweis":"in dicke Scheiben"},{"menge":2,"einheit":"Stück","name":"Süßkartoffeln","hinweis":"in 3 cm Würfel"},{"menge":300,"einheit":"g","name":"Weißkohl","hinweis":"in Spalten"},{"menge":2,"einheit":"Stück","name":"Kartoffeln","hinweis":"in Stücke"}]}],"ausruestung":["schwerer Schmortopf","Holzlöffel","Schüssel"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Fleisch in gleichmäßige Würfel von 3–4 cm; kleinere Stücke zerfallen im Schmoren, größere werden zäh. Hacke Zwiebeln und Knoblauch, reibe den Ingwer und schneide das Gemüse in grobe Stücke, denn es soll lange mitgaren, ohne zu zerfallen. Stelle die Erdnussbutter bereit und rühre sie mit etwas heißem Wasser glatt, wenn sie fest ist. Tupfe das Fleisch mit Küchenpapier gut trocken.","dauer":20,"tipp":""},{"titel":"Fleisch anbraten","aktion":"anbraten","text":"Erhitze das Erdnussöl in einem schweren Topf bei hoher Hitze und brate das Fleisch portionsweise 3–4 Minuten pro Seite an, bis es tiefbraun und krustig ist. Überfülle den Topf nicht, sonst kocht das Fleisch statt zu bräunen. Das Anbraten liefert die Röstaromen, die der Sauce Tiefe geben. Nimm das Fleisch nach dem Bräunen heraus und lege es beiseite.","dauer":15,"tipp":""},{"titel":"Zwiebeln und Gewürze anschwitzen","aktion":"anbraten","text":"Gib die Zwiebeln in den Bratensatz und schwitze sie 8–10 Minuten, bis sie weich und goldbraun sind. Rühre Knoblauch und Ingwer ein und röste sie 1 Minute, bis es duftet. Füge Thymian und Lorbeer zu. Die Zwiebeln lösen den Bratensatz vom Boden und färben dadurch die Sauce intensiver. Löse den Bratensatz mit einem Löffel vom Boden, er färbt die Sauce später tiefbraun und gibt ihr Fleischgeschmack. Bräunen die Zwiebeln zu schnell, gieße einen Schuss Wasser nach und senke die Hitze.","dauer":12,"tipp":""},{"titel":"Tomatenmark rösten","aktion":"anbraten","text":"Gib das Tomatenmark hinzu und röste es 3–4 Minuten bei mittlerer Hitze, bis es dunkler und süßlicher riecht. Gieße die stückigen Tomaten dazu und koche alles 5 Minuten ein. Das Anrösten nimmt dem Mark die Säure und färbt die Sauce satt rot-braun. Rühre häufig, damit nichts am Boden festbrennt. Der Ansatz ist richtig, wenn das Mark am Rand rostbraun wird und sich ein dünner, rötlicher Ölfilm absetzt. Dann hat es seine Rohschärfe verloren und bringt die gewünschte Süße und Farbe in den Eintopf.","dauer":8,"tipp":""},{"titel":"Schmoren beginnen","aktion":"schmoren","text":"Lege das Fleisch zurück in den Topf und gieße Wasser oder Brühe an, bis es knapp bedeckt ist. Lege die ganze Scotch Bonnet hinein; sie gibt Aroma, aber wenig Schärfe, solange sie heil bleibt. Bringe es zum Kochen, reduziere die Hitze und schmore es zugedeckt 60 Minuten. Das Fleisch soll am Ende fast zerfallen.","dauer":60,"tipp":""},{"titel":"Erdnusssauce einrühren","aktion":"mischen","text":"Gib die Erdnussbutter in eine Schüssel, rühre eine große Kelle heiße Fleischbrühe hinein, bis eine glatte Sauce entsteht, und gieße sie in den Topf. Rühre gut um, damit sich nichts am Boden festsetzt. Die Sauce wird dadurch dicker, cremiger und nussig-rund. Köchle weitere 10 Minuten bei niedriger Hitze.","dauer":10,"tipp":"Erdnussbutter brennt leicht an – immer niedrig kochen und rühren."},{"titel":"Gemüse zugeben","aktion":"koecheln","text":"Gib Karotten, Süßkartoffeln, Kartoffeln und Kohl in den Topf und schmore sie 25–30 Minuten, bis sie weich sind. Härteres Gemüse zuerst, Kohl zuletzt. Das Öl der Erdnüsse steigt als rötlicher Film nach oben, ein sicheres Zeichen, dass die Sauce gelungen ist. Rühre vorsichtig, damit das Gemüse heil bleibt.","dauer":30,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere die Sauce: Sie soll kräftig, nussig, leicht süßlich von den Karotten und leicht scharf sein. Fehlt Würze, gib Salz oder etwas mehr Tomate hinzu; ist sie zu dick, verdünne mit heißem Wasser. Ein Spritzer Limettensaft bringt Frische. Die ganze Chili vor dem Servieren herausnehmen. Prüfe auch, ob das Fleisch gar ist: Es soll mit einem leichten Druck der Gabel zerfallen. Falls die Sauce zu dünn ist, koche sie offen 10 Minuten ein, bis sie einen Löffelrücken überzieht.","dauer":5,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Schöpfe Fleisch, Gemüse und Sauce auf Reis. Die Sauce wird mit Reis aufgenommen. Traditionell isst man aus einer gemeinsamen Schüssel. Dazu passen Chili-Sauce, Zitronenspalten und frischer Koriander. Mafé schmeckt aufgewärmt am nächsten Tag noch besser. Reiche frischen Koriander und Limettenspalten dazu, die Frische schneidet durch die Fülle der Erdnusssauce. Wenn du magst, kannst du eine scharfe Paste (Piment) separat reichen.","dauer":0,"tipp":""}],"profitipps":["Nur ungesüßte Erdnussbutter ohne Zusätze verwenden.","Erdnusspaste mit heißer Brühe anrühren, damit sie nicht klumpt.","Am Ende setzt sich Öl oben ab – das ist erwünscht.","Gemüse gestaffelt zugeben, damit alles gleichzeitig gar ist.","Scotch Bonnet ganz lassen für milderes Aroma."],"varianten":["Mit Huhn","Mit Lamm","Vegetarisch mit Süßkartoffeln und Okra"],"beilagen":["Weißer Reis","Fonio","Fladenbrot"],"getraenk":"Bissap (Hibiskus) oder Ingwersaft","koeche":[{"name":"Pierre Thiam","bezug":"Der senegalesische Küchenchef und Autor beschreibt in seinen Büchern und Interviews die schichtweise Aromenbildung der senegalesischen Küche, zu der auch Erdnuss-Eintöpfe wie Mafé zählen.","quelle":"https://www.saveur.com/article/Kitchen/Senegal-Pierre-Thiam"}],"quellen":[{"titel":"Saveur – The Flavors of Senegal (Pierre Thiam)","url":"https://www.saveur.com/article/Kitchen/Senegal-Pierre-Thiam"},{"titel":"WNYC – The Flavors of Modern Day Senegal","url":"https://wnyc.org/story/flavors-modern-day-senegal"},{"titel":"OkayAfrica – 50 of the Best African Foods","url":"https://okayafrica.com/african-countries-best-food-dishes-cuisine"}],"bild":"eintopf","farben":["#a8541f","#e8b04a","#6b3a1a"],"schlagworte":["Westafrika","Erdnuss","Eintopf","Senegal"],"vegetarisch_moeglich":true},{"id":"westafrika-attieke-poisson-braise","name":"Attiéké mit gegrilltem Fisch (Poisson braisé)","originalname":"Attiéké et poisson braisé","kueche":"westafrika","region":"Elfenbeinküste (Abidjan)","beliebtheit":72,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"fisch","gang":"hauptgericht","kurz":"Zartes Maniok-Couscous mit ganz gegrilltem, würzig mariniertem Fisch, scharfer Zwiebel-Tomaten-Sauce, frischem Salat und gebratenen Kochbananen.","hintergrund":"Attiéké ist das Aushängeschild der ivorischen Küche: ein feines, leicht säuerliches Couscous aus fermentiertem Maniok. In den Maquis, den einfachen Straßenrestaurants von Abidjan, wird es mit „poisson braisé“, auf Holzkohle gegrilltem Fisch, gegessen, dazu Zwiebel-Tomaten-Sauce, rohe Salatscheiben und Alloco (frittierte Kochbananen). Das Gericht wird meist mit den Fingern gegessen. Häufig nimmt man Tilapia; in Deutschland sind Dorade oder Wolfsbarsch gute Alternativen.","portionen":4,"zeit":{"vorbereitung":40,"garen":45,"ruhen":60},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":2,"einheit":"Stück","name":"Goldbrassen (Dorade), küchenfertig, je ca. 450 g","hinweis":"Tilapia, Wolfsbarsch oder Forelle gehen ebenso"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ingwerstück (ca. 3 cm)","hinweis":""},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet","hinweis":"oder 2 rote Chilis"},{"menge":1.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Thymian","hinweis":""},{"menge":3,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":3,"einheit":"EL","name":"Öl","hinweis":""}]},{"gruppe":"Attiéké","liste":[{"menge":500,"einheit":"g","name":"Attiéké (tiefgekühlt oder getrocknet)","hinweis":"Afroshop; Ersatz: feiner Couscous, dann ohne die säuerliche Note"},{"menge":1,"einheit":"Tasse","name":"Wasser","hinweis":"zum Befeuchten"},{"menge":1,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Zitronensaft","hinweis":""}]},{"gruppe":"Zwiebel-Tomaten-Sauce","liste":[{"menge":3,"einheit":"Stück","name":"große Zwiebeln","hinweis":"in Halbringen"},{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":"gewürfelt"},{"menge":2,"einheit":"EL","name":"Öl","hinweis":""},{"menge":1,"einheit":"TL","name":"Chilipulver oder 1 frische Chili","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"EL","name":"Zitronensaft","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Brühwürfel","hinweis":"optional"}]},{"gruppe":"Beilagen","liste":[{"menge":2,"einheit":"Stück","name":"reife Kochbananen","hinweis":"für Alloco"},{"menge":300,"einheit":"ml","name":"Öl","hinweis":"zum Braten der Kochbananen"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"für den Salat"},{"menge":0.5,"einheit":"Stück","name":"Salatgurke","hinweis":""},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":""}]}],"ausruestung":["Grill oder Backofen mit Grillfunktion","Dampfeinsatz oder Sieb über Topf","Pfanne","Schüsseln"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Stelle alle Zutaten bereit. Spüle die Fische innen und außen ab und tupfe sie trocken. Schneide Zwiebeln für die Sauce in Halbringe, würfle Tomaten und bereite Salatzutaten vor. Die Kochbananen werden erst kurz vor dem Braten geschält. Wenn dein Attiéké tiefgekühlt ist, taue ihn über Nacht im Kühlschrank oder nach Packungsangabe auf.","dauer":15,"tipp":""},{"titel":"Fisch einritzen und marinieren","aktion":"marinieren","text":"Zerstoße Zwiebel, Knoblauch, Ingwer, Chili, Salz, Thymian und Zitronensaft zu einer groben Paste und rühre das Öl ein. Ritze die Fische auf beiden Seiten 3–4 Mal schräg ein, damit die Marinade tief eindringt, und reibe sie innen und außen kräftig damit ein. Decke sie ab und lasse sie 1 Stunde im Kühlschrank ziehen. Der Fisch nimmt Zitrone und Gewürze auf, ohne dass die Säure das Fleisch weißlich-garziehen lässt.","dauer":60,"tipp":""},{"titel":"Zwiebel-Tomaten-Sauce kochen","aktion":"schmoren","text":"Erhitze das Öl in einer Pfanne und dünste die Zwiebelringe bei mittlerer Hitze 8–10 Minuten glasig-weich. Gib Knoblauch, Chili und Tomaten dazu und lasse die Sauce 10–15 Minuten bei kleiner Hitze einkochen, bis die Flüssigkeit verdampft ist und das Öl glänzt. Würze mit Salz, evtl. Brühwürfel und Zitronensaft. Die Sauce soll sämig, süßlich, scharf und leicht säuerlich sein.","dauer":25,"tipp":""},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Heize die Holzkohle an, bis sie von weißer Asche bedeckt ist, oder schalte den Backofen auf Grillfunktion (250 °C). Reibe den Rost mit Öl ein. Lege die Fische erst auf den Rost, wenn er richtig heiß ist, damit die Haut nicht klebt. Rechne mit 180–200 °C direkter Hitze und einem kühleren Bereich, in den du die Fische zum Fertiggaren verschiebst.","dauer":15,"tipp":""},{"titel":"Fisch grillen","aktion":"grillen","text":"Grille die Fische 8–10 Minuten pro Seite, bis die Haut knusprig, goldbraun und stellenweise dunkel gebräunt ist. Wende sie nur einmal und wenn sie sich gelöst haben. Der Fisch ist gar, wenn das Fleisch an der dicksten Stelle weiß und saftig ist (ca. 62–65 °C) und sich die Rückenflosse leicht herausziehen lässt. Beträufele ihn zum Schluss mit etwas Marinade-Öl.","dauer":20,"tipp":"Lege die Fische kurz in Alufolie auf die kühle Seite, falls die Haut dunkel wird, bevor das Innere gar ist."},{"titel":"Attiéké dämpfen","aktion":"daempfen","text":"Befeuchte den Attiéké mit etwas Wasser (ca. 1 Tasse auf 500 g) und lockere ihn mit den Fingern auf. Fülle ihn in ein Sieb oder einen Dämpfeinsatz über kochendem Wasser, decke ab und dämpfe 20 Minuten, bis er heiß, weich und aufgequollen ist. Gib ihn danach in eine Schüssel, würze mit Salz, Öl und einigen Tropfen Zitronensaft und lockere ihn mit einer Gabel. Er soll fluffig und körnig sein, nicht klebrig.","dauer":20,"tipp":""},{"titel":"Alloco braten","aktion":"frittieren","text":"Schäle die Kochbananen, schneide sie schräg in 1 cm dicke Scheiben und brate sie in 1–2 cm heißem Öl bei mittlerer Hitze 2–3 Minuten pro Seite, bis sie goldbraun und karamellisiert sind. Lege sie auf Küchenpapier und salze sie leicht. Sie sollen außen knusprig und innen cremig-süß sein; ein paar dunkle Ränder sind genau richtig.","dauer":10,"tipp":""},{"titel":"Salat und Servieren","aktion":"anrichten","text":"Mische Tomaten, Gurke und Zwiebel mit etwas Öl, Salz und Zitronensaft. Richte den Attiéké als Häufchen an, setze den Fisch daneben und gib reichlich Zwiebel-Tomaten-Sauce darüber. Serviere Alloco und Salat dazu. Gegessen wird in Abidjan mit den Fingern: Man formt aus Attiéké, Sauce und Fisch kleine Bissen.","dauer":5,"tipp":""}],"profitipps":["Attiéké immer dämpfen oder kurz erhitzen und nicht einweichen – er soll körnig bleiben, nicht matschig.","Marinade: Zitrone nur kurz einwirken lassen, sonst verliert der Fisch Festigkeit.","Ganzer Fisch auf der Gräte bleibt saftiger als Filet.","Kochbananen müssen sehr reif sein – die Schale ist fast schwarz.","Die scharfe Zwiebelsauce lässt sich gut vorbereiten und schmeckt am nächsten Tag noch besser."],"varianten":["Poulet braisé: gegrilltes Hähnchen statt Fisch.","Garba: Attiéké mit frittiertem Thunfisch, ein einfaches Straßengericht in Abidjan.","Attiéké mit Kapitän (Nilbarsch) oder Karpfen.","Mit gegrillten Garnelen statt Fisch."],"beilagen":["Zwiebel-Tomaten-Sauce","Alloco (frittierte Kochbananen)","Tomaten-Gurken-Salat","scharfe Pfeffersauce"],"getraenk":"Gekühlter Bissap, Ingwersaft oder kühles Bier","koeche":[],"quellen":[{"titel":"Do It In Paris – Attiéké (Ivorian recipe)","url":"https://www.doitinparis.com/en/recette-attieke-25819&prev=true"},{"titel":"Marty Made It – Côte d’Ivoire: Poisson braisé","url":"https://martymadeit.com/2017/05/16/042-cote-divoire-ivory-coast-poisson-braise/"}],"bild":"fisch","farben":["#b8860b","#e8c36a","#f7efd5"],"schlagworte":["Elfenbeinküste","Maniok","Grillfisch","Maquis"],"themen":["grill","streetfood"],"vegetarisch_moeglich":false},{"id":"westafrika-chin-chin","name":"Chin Chin – knusprige Teigwürfel aus Nigeria","originalname":"Chin Chin","kueche":"westafrika","region":"Nigeria (auch Ghana, Togo, Benin)","beliebtheit":70,"hauptkategorie":"suess","fleischsorte":"","fischsorte":"","gang":"gebaeck","kurz":"Kleine frittierte Teigwürfel mit Muskat und Butter – knusprig, nussig-süß, perfekt zum Naschen und Verschenken.","hintergrund":"Chin Chin ist ein knuspriger Snack aus Nigeria: Ein fester Mürbeteig aus Mehl, Zucker, Butter und Milch wird in kleine Stücke geschnitten und frittiert. Er heißt in Togo und Benin Atchomon, in Ghana Achomo und in Kamerun Croquette. Man knabbert Chin Chin als Snack, auf Partys und zu Feiertagen; in einer Dose hält es sich mehrere Wochen. Zu den typischen Gewürzen zählt frisch geriebene Muskatnuss.","portionen":6,"zeit":{"vorbereitung":30,"garen":25,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Teig","liste":[{"menge":400,"einheit":"g","name":"Weizenmehl Type 405","hinweis":""},{"menge":80,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"frisch geriebene Muskatnuss","hinweis":""},{"menge":80,"einheit":"g","name":"kalte Butter","hinweis":"in kleinen Würfeln"},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":"Größe M"},{"menge":100,"einheit":"ml","name":"Milch","hinweis":"ca., nach Bedarf"},{"menge":1,"einheit":"TL","name":"Abrieb einer Bio-Zitrone","hinweis":"optional"}]},{"gruppe":"Zum Frittieren","liste":[{"menge":1,"einheit":"l","name":"Pflanzenöl","hinweis":"neutral, z. B. Raps- oder Erdnussöl"}]}],"ausruestung":["große Schüssel","Nudelholz","scharfes Messer oder Teigrädchen","hoher Topf oder Fritteuse","Küchenthermometer","Schaumlöffel","luftdichte Dose"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Mehl, Zucker, Backpulver und Salz ab, würfle die kalte Butter in 1 cm große Stücke und reibe die Muskatnuss frisch. Stelle Ei und Milch bereit und halte das Öl griffbereit. Kalte Butter ist wichtig, weil sie sich beim Einarbeiten mit dem Mehl zu feinen Krümeln verbindet und dem Teig seinen mürben Biss gibt. Hole eine Arbeitsfläche, auf der du den Teig ausrollen kannst.","dauer":8,"tipp":""},{"titel":"Butter einarbeiten","aktion":"mischen","text":"Vermische Mehl, Zucker, Backpulver, Salz, Muskat und Zitronenabrieb in einer Schüssel. Gib die kalten Butterwürfel hinzu und reibe sie mit den Fingerspitzen in das Mehl, bis eine krümelige, sandige Masse entsteht, in der keine Butterstücke mehr zu sehen sind. Arbeite zügig, damit die Butter nicht schmilzt. Die Krümel sollen sich beim Zusammendrücken wie feuchter Sand halten.","dauer":5,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Verquirle Ei und 80 ml Milch und gieße beides in die Mulde. Verknete alles zu einem festen, glatten Teig und gib bei Bedarf noch etwas Milch dazu. Er soll sich fest wie Nudelteig anfühlen, nicht kleben und nicht bröckeln. Knete ihn 3–4 Minuten, bis er elastisch ist und eine glatte Oberfläche hat. Zu weicher Teig wird beim Frittieren dick und fettig; zu fester wird hart.","dauer":6,"tipp":""},{"titel":"Teig ruhen lassen","aktion":"ruhen","text":"Wickle den Teig in Frischhaltefolie und lasse ihn 30 Minuten bei Zimmertemperatur ruhen. Das Gluten entspannt sich, und der Teig lässt sich später dünn ausrollen, ohne zurückzuschnappen. Beim Berühren fühlt er sich danach geschmeidig und weich an. Du kannst ihn auch bis zu 24 Stunden gekühlt aufbewahren, lasse ihn dann aber vor dem Ausrollen 15 Minuten temperieren.","dauer":30,"tipp":""},{"titel":"Ausrollen und schneiden","aktion":"ausrollen","text":"Rolle den Teig auf einer leicht bemehlten Fläche etwa 5 mm dick aus. Schneide ihn mit einem scharfen Messer oder Teigrädchen in etwa 1,5 cm breite Streifen und dann quer in kleine Würfel oder Rauten. Die Stücke sollen gleich groß sein, damit sie gleichmäßig bräunen. Bestreue sie leicht mit Mehl, damit sie nicht zusammenkleben, und schüttle überschüssiges Mehl vor dem Frittieren ab.","dauer":15,"tipp":""},{"titel":"Öl erhitzen","aktion":"frittieren","text":"Erhitze das Öl in einem hohen Topf auf 170 °C; der Topf darf höchstens zu einem Drittel gefüllt sein. Teste mit einem Teigstück: Es soll sofort aufsteigen, sprudeln und nach 20–30 Sekunden hellgolden werden. Ist das Öl zu heiß, bräunen die Würfel außen und bleiben innen roh; ist es zu kalt, saugen sie sich mit Öl voll. Lege Küchenpapier und einen Schaumlöffel bereit, denn das Frittieren geht dann schnell.","dauer":8,"tipp":""},{"titel":"Frittieren","aktion":"frittieren","text":"Frittiere die Würfel in kleinen Portionen und rühre sie ständig mit dem Schaumlöffel um, damit sie gleichmäßig Farbe nehmen. Nach 3–4 Minuten sind sie goldbraun, knusprig und riechen nach Butter und Muskat. Hebe sie mit dem Schaumlöffel heraus und lasse sie auf Küchenpapier abtropfen. Sie härten beim Abkühlen noch nach, zögere also nicht, sie schon bei hellem Goldton herauszunehmen.","dauer":15,"tipp":"Dunkel gebackene Würfel schmecken bitter – lieber ein wenig früher herausnehmen."},{"titel":"Abkühlen und lagern","aktion":"kuehlen","text":"Lasse Chin Chin vollständig auskühlen, bevor du es in eine luftdichte Dose füllst. Wenn es noch warm ist, schwitzt es im Behälter und wird weich. Gut verschlossen hält es sich 2–3 Wochen. Es knackt beim Abbeißen laut und schmeckt buttrig, leicht süß und nach Muskat. Zum Auffrischen genügen 5 Minuten im 150 °C warmen Backofen.","dauer":10,"tipp":""}],"profitipps":["Der Teig muss fest sein: Wie Nudelteig, nicht wie Plätzchenteig.","Dünn ausrollen (4–5 mm), dann werden die Würfel knusprig statt hart.","Muskat frisch reiben – das Aroma macht Chin Chin aus.","Öl nicht zu heiß werden lassen; sonst bräunt die Außenseite, bevor das Innere durch ist.","In einer Blechdose lagern, nicht in Plastik – so bleibt die Knusprigkeit länger."],"varianten":["Mit Zimt, Vanille oder Orangenabrieb.","Gebacken statt frittiert: 20 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft), dabei einmal wenden.","Mit Kokosraspeln im Teig.","Herzhafte Version mit Chili und Salz statt Zucker."],"beilagen":["Tee oder Kaffee","Zobo (Hibiskusgetränk)","Fruchtsaft"],"getraenk":"Tee, Kaffee oder kalter Hibiskustee (Zobo)","koeche":[],"quellen":[{"titel":"Wikipedia – Chin chin","url":"https://en.wikipedia.org/wiki/Chin_chin"},{"titel":"Wikipedia – Nigerian cuisine","url":"https://en.wikipedia.org/wiki/Nigerian_cuisine"}],"bild":"gebaeck","farben":["#b8782c","#e3b562","#f8ecd0"],"schlagworte":["Knabberei","Nigeria","Verschenken","Frittiertes"],"vegetarisch_moeglich":true},{"id":"westafrika-ndole","name":"Ndolé – Kameruns Nationalgericht mit Erdnüssen und Garnelen","originalname":"Ndolé","kueche":"westafrika","region":"Kamerun (Douala)","beliebtheit":68,"hauptkategorie":"fisch","fleischsorte":"","fischsorte":"gemischt","gang":"hauptgericht","kurz":"Zarte Bitterblätter in cremiger Erdnusssauce mit Garnelen und Räucherfisch – würzig, nussig, mit angenehmem Bitterton.","hintergrund":"Ndolé gilt als Nationalgericht Kameruns und stammt aus Douala an der Küste. Seinen Namen hat es von den Blättern der Ndolé-Pflanze, einer Bitterblatt-Art, die vor dem Kochen mehrfach blanchiert wird, damit sie nur noch angenehm herb schmecken. Die Blätter werden in eine Sauce aus frisch gemahlenen Erdnüssen, Zwiebeln, Knoblauch und Krebsen eingerührt; dazu kommen Rindfleisch, Fisch oder Garnelen. Die Version mit Garnelen heißt „royal“. Dazu isst man Kochbananen, Bobolo oder Miondo (gedämpfte Maniokstangen) oder Maniok.","portionen":4,"zeit":{"vorbereitung":40,"garen":130,"ruhen":0},"schwierigkeit":3,"zutaten":[{"gruppe":"Blätter","liste":[{"menge":400,"einheit":"g","name":"Ndolé-Blätter (Bitterleaf), tiefgekühlt oder getrocknet","hinweis":"Afroshop; Ersatz: 500 g Spinat plus 150 g Mangold oder Rucola – Bitterkeit nach Geschmack"},{"menge":1,"einheit":"EL","name":"Salz","hinweis":"zum Blanchieren"}]},{"gruppe":"Erdnusspaste","liste":[{"menge":250,"einheit":"g","name":"rohe, geschälte Erdnüsse","hinweis":"Reformhaus oder Asiashop; ungesalzene geröstete gehen notfalls"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"grob geschnitten"},{"menge":5,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ingwerstück (ca. 4 cm)","hinweis":""}]},{"gruppe":"Sauce und Einlagen","liste":[{"menge":100,"einheit":"ml","name":"Erdnussöl","hinweis":""},{"menge":2,"einheit":"Stück","name":"Zwiebeln","hinweis":"fein gehackt"},{"menge":2,"einheit":"EL","name":"gemahlene getrocknete Krebse (Crayfish)","hinweis":"Afroshop; Ersatz: 1 TL Fischsauce plus 1 TL gemahlene Garnelenschalen oder getrocknete Garnelen"},{"menge":400,"einheit":"g","name":"Garnelen, roh, geschält und entdarmt","hinweis":""},{"menge":200,"einheit":"g","name":"Räucherfisch ohne Gräten","hinweis":"geräucherter Kabeljau oder Seelachs"},{"menge":1,"einheit":"Stück","name":"Brühwürfel","hinweis":""},{"menge":1,"einheit":"Stück","name":"Scotch Bonnet","hinweis":"ganz"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":500,"einheit":"ml","name":"Wasser oder Fischfond","hinweis":""}]}],"ausruestung":["großer Topf","Mixer oder Stabmixer","Sieb","Holzlöffel","Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Taue die Blätter über Nacht im Kühlschrank auf oder weiche getrocknete Blätter nach Packungsangabe ein. Spüle Garnelen kalt ab, tupfe sie trocken und würze sie mit etwas Salz. Zerpflücke den Räucherfisch in grobe Stücke und prüfe auf Gräten. Schneide Zwiebeln fein, Knoblauch und Ingwer grob, und lege Erdnüsse und Gewürze bereit. Bei diesem Gericht entscheidet die Vorarbeit – die Sauce braucht Zeit, aber wenig Aufmerksamkeit.","dauer":15,"tipp":""},{"titel":"Blätter blanchieren","aktion":"blanchieren","text":"Bringe 2 Liter Wasser mit dem Salz zum Kochen, gib die Blätter hinein und koche sie 5 Minuten. Gieße ab und drücke die Blätter kräftig aus. Wiederhole den Vorgang noch ein- bis zweimal mit frischem Salzwasser. Probiere zwischendurch eine kleine Menge: Die Bitterkeit soll angenehm herb, nicht beißend sein. Dann drückst du die Blätter fest aus und hackst sie grob. Der Geruch ist dabei grün-erdig mit leichtem Bitterton.","dauer":15,"tipp":"Ersatz-Greens (Spinat, Mangold) brauchen nur einmal kurz zu blanchieren; für die Bitterkeit ein paar Rucolablätter oder Radicchio dazugeben."},{"titel":"Erdnüsse garen","aktion":"kochen","text":"Gib die Erdnüsse in einen Topf, bedecke sie mit Wasser und koche sie 30–40 Minuten, bis sie weich sind und sich leicht zerdrücken lassen. Gieße sie ab und fange einen Teil des Kochwassers auf. Rohe Erdnüsse haben einen milden, leicht grünen Geschmack und werden beim Kochen cremig. Ungesalzene geröstete Erdnüsse brauchen nur 10 Minuten in kochendem Wasser, damit sie weich werden.","dauer":40,"tipp":""},{"titel":"Erdnusspaste pürieren","aktion":"puerieren","text":"Püriere die gekochten Erdnüsse zusammen mit Zwiebel, Knoblauch, Ingwer und 200–250 ml Kochwasser im Mixer zu einer sehr feinen, cremigen Paste. Sie soll glatt wie Erdnussbutter sein, aber noch gießbar. Zu grob verfehlt die Textur der Sauce, zu flüssig verlängert die Garzeit. Ein nussig-warmer Duft nach Erdnüssen und Knoblauch zeigt, dass die Aromen eingebunden sind.","dauer":8,"tipp":""},{"titel":"Basis anbraten","aktion":"anbraten","text":"Erhitze das Öl in einem großen Topf bei mittlerer Hitze und dünste die gehackten Zwiebeln 6–8 Minuten glasig. Gib die gemahlenen Krebse hinein und rühre 1 Minute, bis es nach Meer und Röstaromen riecht. Die Zwiebeln sollen nur weich werden, nicht braun. Gib dann die Erdnusspaste hinzu und rühre 5 Minuten, damit sie anröstet und das Aroma sich vertieft.","dauer":15,"tipp":""},{"titel":"Sauce köcheln lassen","aktion":"koecheln","text":"Gieße 500 ml Wasser oder Fischfond zu, gib Brühwürfel, Salz und die ganze Chili dazu und rühre glatt. Lasse die Sauce 25–30 Minuten bei kleiner Hitze köcheln und rühre häufig, damit nichts anbrennt. Sie ist fertig, wenn sie dick, samtig ist und an der Oberfläche Öl austritt – ein Zeichen, dass die Erdnüsse gar sind. Schmecke ab: Sie soll nussig, herzhaft und leicht salzig schmecken.","dauer":30,"tipp":"Die Chili ganz lassen; platzt sie, wird die Sauce sehr scharf."},{"titel":"Blätter und Räucherfisch einrühren","aktion":"mischen","text":"Rühre die ausgedrückten, gehackten Blätter in die Sauce und lasse alles 10–15 Minuten bei niedriger Hitze ziehen. Gib den Räucherfisch dazu. Die Blätter verbinden sich mit der Sauce zu einer dunkelgrünen, cremigen Masse mit leicht herbem Geschmack. Ist die Sauce zu dick, gieße etwas Wasser nach; sie soll wie dicker Spinatrahm sein.","dauer":15,"tipp":""},{"titel":"Garnelen garen","aktion":"braten","text":"Erhitze 2 EL Öl in einer Pfanne und brate die Garnelen bei hoher Hitze 2–3 Minuten, bis sie rosa sind und eingerollt. Zu langes Braten macht sie gummiartig. Gib sie in die Sauce, rühre kurz um und nimm den Topf vom Herd. Der Duft nach Meer und Erdnuss sollte jetzt intensiv sein. Lasse alles 5 Minuten ruhen, damit sich die Aromen verbinden.","dauer":8,"tipp":""},{"titel":"Abschmecken und anrichten","aktion":"anrichten","text":"Probiere die Sauce: Sie soll nussig, salzig, leicht bitter und fischig-würzig sein. Falls sie zu bitter ist, hilft eine Prise Zucker. Richte den Ndolé in tiefen Tellern an und serviere ihn mit gebratenen Kochbananen, Bobolo oder Reis. In Kamerun reißt man Stücke von Bobolo oder Maniok ab und nimmt damit die Sauce auf.","dauer":5,"tipp":""}],"profitipps":["Die Bitterkeit der Blätter ist gewünscht – sie macht den Charakter des Gerichts. Blanchiere bis zum gewünschten Grad.","Erdnusspaste sorgfältig und lange rösten und köcheln; sie darf nicht pappig-roh schmecken.","Krebs- oder Garnelenpulver bringt Umami, ersatzweise ein Schuss Fischsauce.","Garnelen immer zuletzt garen, sonst werden sie zäh.","Der Eintopf schmeckt am zweiten Tag besonders gut."],"varianten":["Ndolé mit Rindfleisch statt Garnelen – die klassische Fleischversion.","Mit Räucherfisch und Hähnchen.","„Royal“ mit Garnelen und Fleisch.","Vegetarisch mit Räuchertofu und Pilzen."],"beilagen":["gebratene Kochbananen","Bobolo oder Miondo","Maniok oder Reis"],"getraenk":"Palmwein, kühles Lagerbier oder ein leichter Weißwein","koeche":[],"quellen":[{"titel":"Wikipedia – Ndolé","url":"https://en.wikipedia.org/wiki/Ndol%C3%A9"},{"titel":"Africa.com – Ndolé, Cameroonian national dish","url":"https://africa.com/lifestyle/ndole-cameroonian-national-dish"}],"bild":"eintopf","farben":["#3f5a2a","#8a7a3a","#e3cfa0"],"schlagworte":["Kamerun","Erdnuss","Nationalgericht","Bitterblätter"],"vegetarisch_moeglich":false}]);
